package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

final class BackgroundOpacity
{
    static int clamp(int percent) { return Math.max(0, Math.min(100, percent)); }
    static int effective(int requested, boolean supported) { return supported ? clamp(requested) : 100; }
    static int alpha(int percent) { return (clamp(percent) * 255 + 50) / 100; }
    static Color color(int percent)
    {
        int rgb = ModelRenderer.BACKGROUND;
        return new Color((rgb >> 16) & 255, (rgb >> 8) & 255, rgb & 255, alpha(percent));
    }

    /** Reference compositing also used by static renderer tests: background alpha never scales models. */
    static BufferedImage compose(BufferedImage models, int percent)
    {
        BufferedImage image = new BufferedImage(models.getWidth(), models.getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            g.setComposite(AlphaComposite.Src);
            g.setColor(color(percent));
            g.fillRect(0,0,image.getWidth(),image.getHeight());
            g.setComposite(AlphaComposite.SrcOver);
            g.drawImage(models,0,0,null);
        }
        finally { g.dispose(); }
        return image;
    }
}

package com.modelpopout;

/** Immutable viewer-only camera settings, passed from the EDT to the renderer. */
final class CameraView
{
    static final double MIN_PITCH = Math.toRadians(-75);
    static final double MAX_PITCH = Math.toRadians(75);
    static final double MIN_ZOOM = .4;
    static final double MAX_ZOOM = 3;
    // Native player models face negative Z; yaw zero looks at that front surface.
    static final CameraView DEFAULT = new CameraView(0, Math.toRadians(10), 1);
    final double yaw, pitch, zoom;

    CameraView(double yaw, double pitch, double zoom)
    {
        if (!Double.isFinite(yaw) || !Double.isFinite(pitch) || !Double.isFinite(zoom))
        {
            throw new IllegalArgumentException("Camera settings must be finite");
        }
        double turn = Math.PI * 2;
        this.yaw = (yaw % turn + turn) % turn;
        this.pitch = Math.max(MIN_PITCH, Math.min(MAX_PITCH, pitch));
        this.zoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, zoom));
    }

    CameraView drag(int dx, int dy)
    {
        return new CameraView(yaw + dx * .01, pitch + dy * .01, zoom);
    }

    CameraView wheel(double turns)
    {
        // Clamp wheel input before exponentiation, including high-resolution wheels.
        double exponent = Math.max(-20, Math.min(20, -turns * .12));
        return new CameraView(yaw, pitch, zoom * Math.exp(exponent));
    }
}

package com.modelpopout;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

/** Native-style priority groups, including depth interleaving for priorities 10 and 11. */
final class FaceOrdering
{
    static int[] order(ModelSnapshot mesh, double[] z)
    {
        Integer[] sorted = new Integer[mesh.a.length];
        double[] distance = new double[sorted.length];
        for (int i=0;i<sorted.length;i++) { sorted[i]=i; distance[i]=(z[mesh.a[i]]+z[mesh.b[i]]+z[mesh.c[i]])/3; }
        Arrays.sort(sorted,Comparator.comparingDouble((Integer i) -> -distance[i]));
        if (mesh.priorities == null) return Arrays.stream(sorted).mapToInt(Integer::intValue).toArray();
        List<List<Integer>> groups = new ArrayList<>();
        for (int i=0;i<12;i++) groups.add(new ArrayList<>());
        for (int face : sorted) groups.get(Math.min(11,mesh.priorities[face]&255)).add(face);
        List<Integer> special = new ArrayList<>(groups.get(10)); special.addAll(groups.get(11));
        double[] thresholds = {average(groups,distance,1,2),average(groups,distance,3,4),average(groups,distance,6,8)};
        int[] result = new int[sorted.length]; int out=0, dynamic=0;
        for (int priority=0;priority<10;priority++)
        {
            int threshold = priority == 0 ? 0 : priority == 3 ? 1 : priority == 5 ? 2 : -1;
            if (threshold >= 0) while (dynamic < special.size() && distance[special.get(dynamic)] > thresholds[threshold])
                result[out++] = special.get(dynamic++);
            for (int face : groups.get(priority)) result[out++] = face;
        }
        while (dynamic < special.size()) result[out++] = special.get(dynamic++);
        return result;
    }
    private static double average(List<List<Integer>> groups,double[] depth,int a,int b)
    {
        double sum=0; int count=0;
        for (int group : new int[]{a,b}) for (int face : groups.get(group)) { sum+=depth[face]; count++; }
        return count == 0 ? 0 : sum/count;
    }
}

package com.modelpopout;

/** Independent, monotonic render/presentation deadlines. No catch-up burst after a stall. */
final class FramePacer
{
    private long period, nextRender, nextPresentation;
    private boolean renderingScheduled, presentationScheduled;
    void setTarget(RenderTarget target)
    {
        period = target.fps == 0 ? 0 : 1_000_000_000L / target.fps;
        renderingScheduled = presentationScheduled = false;
    }
    long renderDelay(long now) { return renderingScheduled ? Math.max(0,nextRender-now) : 0; }
    long presentationDelay(long now) { return presentationScheduled ? Math.max(0,nextPresentation-now) : 0; }
    void rendered(long now) { nextRender = deadline(nextRender,renderingScheduled,now); renderingScheduled = true; }
    void presented(long now) { nextPresentation = deadline(nextPresentation,presentationScheduled,now); presentationScheduled = true; }
    private long deadline(long previous,boolean scheduled,long now)
    {
        long next = previous+period;
        return scheduled && period > 0 && next-now > 0 ? next : now+period;
    }
    static int delayMillis(long nanos) { return (int) Math.max(1,Math.min(Integer.MAX_VALUE,(nanos+999_999)/1_000_000)); }
}

package com.modelpopout;

import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import net.runelite.api.HitsplatID;

/** Bounded decoding of the public config archive's hitsplat format, not internal client objects. */
final class HitsplatStyle
{
    final int color,duration,fadeStart,replaceMode,offsetX,offsetY,textOffset,varbit,varp;
    final int[] sprites,transforms;
    final String format;

    private HitsplatStyle(Builder b)
    {
        color=b.color;duration=b.duration;fadeStart=b.fadeStart;replaceMode=b.replaceMode;
        offsetX=b.offsetX;offsetY=b.offsetY;textOffset=b.textOffset;varbit=b.varbit;varp=b.varp;
        sprites=b.sprites.clone();transforms=b.transforms==null?null:b.transforms.clone();format=b.format;
    }

    static HitsplatStyle decode(byte[] data)
    {
        if(data==null || data.length==0 || data.length>4096) throw new IllegalArgumentException("Invalid hitsplat definition size");
        ByteBuffer in=ByteBuffer.wrap(data);Builder b=new Builder();
        while(in.hasRemaining())
        {
            int opcode=in.get()&255;
            switch(opcode)
            {
                case 0:return new HitsplatStyle(b);
                case 1:smart(in);break; // Native font ID: no offscreen native-font API is used.
                case 2:b.color=((in.get()&255)<<16)|((in.get()&255)<<8)|(in.get()&255);break;
                case 3:b.sprites[0]=smart(in);break;
                case 4:b.sprites[1]=smart(in);break;
                case 5:b.sprites[2]=smart(in);break;
                case 6:b.sprites[3]=smart(in);break;
                case 7:b.offsetX=in.getShort();break;
                case 8:
                    if(in.get()!=0) throw new IllegalArgumentException("Invalid hitsplat string marker");
                    int start=in.position();
                    while(in.get()!=0) { /* bounded by the input buffer */ }
                    b.format=new String(data,start,in.position()-start-1,Charset.forName("windows-1252"));
                    break;
                case 9:b.duration=Math.max(1,in.getShort()&65535);break;
                case 10:b.offsetY=in.getShort();break;
                case 11:b.fadeStart=0;break;
                case 12:b.replaceMode=in.get()&255;break;
                case 13:b.textOffset=in.getShort();break;
                case 14:b.fadeStart=in.getShort()&65535;break;
                case 17:case 18:
                    b.varbit=id(in);b.varp=id(in);
                    int fallback=opcode==18?id(in):-1;
                    int count=in.get()&255;b.transforms=new int[count+2];
                    for(int i=0;i<=count;i++) b.transforms[i]=id(in);
                    b.transforms[count+1]=fallback;
                    break;
                default:throw new IllegalArgumentException("Unsupported hitsplat opcode: "+opcode);
            }
        }
        throw new IllegalArgumentException("Unterminated hitsplat definition");
    }

    private static int id(ByteBuffer in) { int value=in.getShort()&65535;return value==65535?-1:value; }
    private static int smart(ByteBuffer in)
    {
        if(in.get(in.position())<0) return in.getInt()&Integer.MAX_VALUE;
        int value=in.getShort()&65535;return value==32767?-1:value;
    }

    static HitsplatStyle fallback(int type)
    {
        Builder b=new Builder();b.replaceMode=0;
        switch(type)
        {
            case HitsplatID.BLOCK_ME:case HitsplatID.BLOCK_OTHER:b.color=0x438cff;break;
            case HitsplatID.POISON:b.color=0x39a83a;break;
            case HitsplatID.VENOM:b.color=0x146126;break;
            case HitsplatID.HEAL:case HitsplatID.SANITY_RESTORE:b.color=0x4ddd78;break;
            case HitsplatID.DISEASE:case HitsplatID.DISEASE_BLOCKED:b.color=0xe8bb34;break;
            case HitsplatID.DAMAGE_ME_CYAN:case HitsplatID.DAMAGE_OTHER_CYAN:case HitsplatID.DAMAGE_MAX_ME_CYAN:
            case HitsplatID.CYAN_UP:case HitsplatID.CYAN_DOWN:b.color=0x42cbd9;break;
            case HitsplatID.DAMAGE_ME_ORANGE:case HitsplatID.DAMAGE_OTHER_ORANGE:case HitsplatID.DAMAGE_MAX_ME_ORANGE:b.color=0xf09731;break;
            case HitsplatID.DAMAGE_ME_YELLOW:case HitsplatID.DAMAGE_OTHER_YELLOW:case HitsplatID.DAMAGE_MAX_ME_YELLOW:b.color=0xf3db43;break;
            case HitsplatID.DAMAGE_ME_WHITE:case HitsplatID.DAMAGE_OTHER_WHITE:case HitsplatID.DAMAGE_MAX_ME_WHITE:b.color=0xffffff;break;
            case HitsplatID.DAMAGE_ME_POISE:case HitsplatID.DAMAGE_OTHER_POISE:case HitsplatID.DAMAGE_MAX_ME_POISE:b.color=0xb287dc;break;
            case HitsplatID.DAMAGE_ME:case HitsplatID.DAMAGE_OTHER:case HitsplatID.DAMAGE_MAX_ME:
            case HitsplatID.BLEED:case HitsplatID.BURN:b.color=0xe44736;break;
            default:b.color=0xb0b0b0;break;
        }
        return new HitsplatStyle(b);
    }

    String text(int amount) { return (format.isEmpty()?"%1":format).replace("%1",Integer.toString(amount)); }

    private static final class Builder
    {
        int color=0xffffff,duration=70,fadeStart=-1,replaceMode=-1,offsetX,offsetY,textOffset,varbit=-1,varp=-1;
        final int[] sprites={-1,-1,-1,-1};int[] transforms;String format="%1";
    }
}

package com.modelpopout;

import java.awt.Point;

/** Stable initial head anchor transformed exactly like its model, independent of later pose bounds. */
final class HudAnchor
{
    private final double x,y,z;
    private final ModelFrame frame;
    private HudAnchor(double x,double y,double z,ModelFrame frame) { this.x=x;this.y=y;this.z=z;this.frame=frame; }
    static HudAnchor initial(ModelSnapshot mesh,ModelFrame frame)
    {
        double top=Double.POSITIVE_INFINITY;
        for(float y:mesh.y) top=Math.min(top,y);
        return new HudAnchor(frame.centerX,top-12,frame.centerZ,frame);
    }
    Point screen(CameraView camera,int width,int height,boolean npcEnabled,int slot,boolean mirrored)
    {
        int slots=npcEnabled?2:1,size=Math.min(width/slots,height);
        int left=(width-size*slots)/2+size*slot,top=(height-size)/2;
        double mx=x-frame.centerX,my=y-frame.centerY,mz=z-frame.centerZ;
        double rx=mx*Math.cos(camera.yaw)+mz*Math.sin(camera.yaw);
        double rz=mz*Math.cos(camera.yaw)-mx*Math.sin(camera.yaw);
        double px=ModelRenderer.SIZE/2.0+rx*frame.scale(camera);
        if(mirrored) px=ModelRenderer.SIZE-px;
        double py=ModelRenderer.SIZE/2.0+(my*Math.cos(camera.pitch)-rz*Math.sin(camera.pitch))*frame.scale(camera);
        int sx=left+(int)Math.round(px*size/ModelRenderer.SIZE),sy=top+(int)Math.round(py*size/ModelRenderer.SIZE);
        return new Point(Math.max(48,Math.min(width-48,sx)),Math.max(64,Math.min(height-8,sy)));
    }
}

package com.modelpopout;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.ui.FontManager;

/** Client-thread public archive/sprite reads; small complete hit images are built once per event. */
final class HudAssets
{
    private final IntFunction<byte[]> definitions;
    private final IntFunction<BufferedImage> sprites;
    private final IntUnaryOperator varbits,varps;
    private final Map<Integer,HitsplatStyle> styles=new LinkedHashMap<Integer,HitsplatStyle>(64,.75f,true)
    {
        @Override protected boolean removeEldestEntry(Map.Entry<Integer,HitsplatStyle> entry) { return size()>64; }
    };
    private HealthSkin healthSkin=HealthSkin.FALLBACK;
    private int nextHealthRetry;
    private boolean healthAttempted;
    HudAssets(IntFunction<byte[]> definitions,IntFunction<BufferedImage> sprites,IntUnaryOperator varbits,IntUnaryOperator varps)
    { this.definitions=definitions;this.sprites=sprites;this.varbits=varbits;this.varps=varps; }

    HitsplatStyle style(int type)
    {
        try
        {
            int id=type;
            for(int depth=0;depth<8;depth++)
            {
                if(id<0) return null; // Native transformation explicitly hides this hit.
                if(id>4095) break;
                HitsplatStyle style=styles.get(id);
                if(style==null)
                {
                    byte[] data=definitions.apply(id);
                    if(data==null) break;
                    style=HitsplatStyle.decode(data);styles.put(id,style);
                }
                if(style.transforms==null) return style;
                int value=style.varbit>=0?varbits.applyAsInt(style.varbit):style.varp>=0?varps.applyAsInt(style.varp):-1;
                id=style.transforms[value>=0 && value<style.transforms.length-1?value:style.transforms.length-1];
            }
        }
        catch(RuntimeException unavailable) { /* unsupported/missing data uses an explicit fallback */ }
        return HitsplatStyle.fallback(type);
    }

    BufferedImage hitImage(int type,HitsplatStyle style,int amount)
    {
        BufferedImage[] parts=new BufferedImage[4];boolean nativeArt=false;
        for(int i=0;i<4;i++) if(style.sprites[i]>=0)
        {
            parts[i]=sprite(style.sprites[i]);nativeArt|=parts[i]!=null;
        }
        BufferedImage measuring=new BufferedImage(1,1,BufferedImage.TYPE_INT_ARGB);
        Graphics2D probe=measuring.createGraphics();FontMetrics metrics;
        try { probe.setFont(FontManager.getRunescapeSmallFont());metrics=probe.getFontMetrics(); }
        finally { probe.dispose(); }
        String text=style.text(amount);
        int textWidth=Math.min(160,metrics.stringWidth(text));
        int icon=width(parts[0]),left=width(parts[1]),right=width(parts[3]);
        int tile=width(parts[2]);
        int middle=tile>0?Math.max(1,(textWidth+4+tile-1)/tile)*tile:textWidth+4;
        int gap=icon>0?2:0;
        int width=Math.max(20,Math.min(256,icon+gap+left+middle+right));
        int height=metrics.getHeight()+4;
        for(BufferedImage part:parts) if(part!=null) height=Math.max(height,part.getHeight());
        height=Math.min(128,height+Math.min(16,Math.abs(style.textOffset)));
        BufferedImage image=new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics();
        try
        {
            g.setFont(FontManager.getRunescapeSmallFont());
            if(!nativeArt)
            {
                g.setColor(new Color(HitsplatStyle.fallback(type).color));g.fillRoundRect(0,0,width,height,10,10);
                g.setColor(Color.BLACK);g.drawRoundRect(0,0,width-1,height-1,10,10);
            }
            int x=0;
            draw(g,parts[0],x,height);x+=icon+gap;
            draw(g,parts[1],x,height);x+=left;
            int textX=x+(middle-textWidth)/2;
            if(tile>0) for(int repeat=0;repeat<middle/tile;repeat++) draw(g,parts[2],x+repeat*tile,height);
            x+=middle;draw(g,parts[3],x,height);
            int baseline=(height-metrics.getHeight())/2+metrics.getAscent()+Math.max(-16,Math.min(16,style.textOffset));
            g.setColor(Color.BLACK);g.drawString(text,textX+1,baseline+1);
            g.setColor(nativeArt?new Color(style.color):Color.WHITE);g.drawString(text,textX,baseline);
        }
        finally { g.dispose(); }
        return image;
    }

    HealthSkin healthSkin(int cycle)
    {
        if(healthSkin==HealthSkin.FALLBACK && (!healthAttempted || cycle-nextHealthRetry>=0))
        {
            healthAttempted=true;nextHealthRetry=cycle+50;
            BufferedImage front=sprite(SpriteID.StandardHealth30.FRONT),back=sprite(SpriteID.StandardHealth30.BACK);
            if(front!=null && back!=null) healthSkin=new HealthSkin(front,back);
        }
        return healthSkin;
    }
    private BufferedImage sprite(int id)
    {
        try
        {
            BufferedImage image=sprites.apply(id);
            return image!=null && image.getWidth()<=256 && image.getHeight()<=128?image:null;
        }
        catch(RuntimeException unavailable) { return null; }
    }
    private static int width(BufferedImage image) { return image==null?0:image.getWidth(); }
    private static void draw(Graphics2D g,BufferedImage image,int x,int height)
    { if(image!=null) g.drawImage(image,x,(height-image.getHeight())/2,null); }

    static final class HealthSkin
    {
        static final HealthSkin FALLBACK=new HealthSkin(null,null);
        final BufferedImage front,back;
        HealthSkin(BufferedImage front,BufferedImage back) { this.front=front;this.back=back; }
        int width() { return back==null?30:back.getWidth(); }
        int height() { return back==null?5:back.getHeight(); }
    }
}

package com.modelpopout;

/** Visibility follows available native health-bar data; NPC fractions never imply exact HP. */
final class HudHealth
{
    static final HudHealth UNKNOWN=new HudHealth(false,0,false,-1,-1);
    final boolean visible,exact;
    final double fraction;
    final int current,maximum;

    private HudHealth(boolean visible,double fraction,boolean exact,int current,int maximum)
    { this.visible=visible;this.fraction=fraction;this.exact=exact;this.current=current;this.maximum=maximum; }

    static HudHealth scaled(int ratio,int scale)
    {
        return ratio<0 || scale<=0 ? UNKNOWN : new HudHealth(true,Math.min(1,ratio/(double)scale),false,-1,-1);
    }

    static HudHealth player(int ratio,int scale,int current,int maximum)
    {
        if(ratio<0 || scale<=0) return UNKNOWN;
        if(current<0 || maximum<=0) return scaled(ratio,scale);
        return new HudHealth(true,Math.min(1,current/(double)maximum),true,current,maximum);
    }

    boolean same(HudHealth other)
    { return other!=null && visible==other.visible && exact==other.exact && fraction==other.fraction && current==other.current && maximum==other.maximum; }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Shape;

/** Independent 2D model/HUD layer: no UI-opacity multiplier and no 3D raster work. */
final class HudPainter
{
    static void paint(Graphics2D graphics,HudSnapshot snapshot,HudAnchor playerAnchor,HudAnchor npcAnchor,
        CameraView camera,int width,int height,boolean npcEnabled,boolean mirrorNpc,long imagePlayerKey,long imageNpcKey,
        boolean showHitsplats,boolean showBars)
    {
        if(snapshot==null || width<=0 || height<=0) return;
        Graphics2D g=(Graphics2D)graphics.create();
        try
        {
            g.setComposite(AlphaComposite.SrcOver);
            if(playerAnchor!=null && snapshot.player.key==imagePlayerKey)
                actor(g,snapshot.player,snapshot.cycle,snapshot.skin,playerAnchor.screen(camera,width,height,npcEnabled,0,false),showHitsplats,showBars);
            if(npcEnabled && npcAnchor!=null && imageNpcKey>=0 && snapshot.npcKey==imageNpcKey)
                actor(g,snapshot.npc,snapshot.cycle,snapshot.skin,npcAnchor.screen(camera,width,height,true,1,mirrorNpc),showHitsplats,showBars);
        }
        finally { g.dispose(); }
    }
    private static void actor(Graphics2D g,HudSnapshot.ActorHud actor,int cycle,HudAssets.HealthSkin skin,Point anchor,boolean hits,boolean bars)
    {
        if(bars && actor.health.visible)
        {
            int width=skin.width(),height=skin.height(),x=anchor.x-width/2,y=anchor.y-height;
            int filled=actor.health.fraction<=0?0:Math.max(1,(int)Math.round(width*actor.health.fraction));
            if(skin.back!=null)
            {
                g.drawImage(skin.back,x,y,null);Shape old=g.getClip();g.clipRect(x,y,filled,height);
                g.drawImage(skin.front,x,y,null);g.setClip(old);
            }
            else
            {
                g.setColor(Color.RED);g.fillRect(x,y,width,height);g.setColor(Color.GREEN);g.fillRect(x,y,filled,height);
            }
        }
        if(!hits) return;
        for(HudSnapshot.Hit hit:actor.hits)
        {
            if(!hit.visible(cycle)) continue;
            int dx=hit.slot==2?-18:hit.slot==3?18:0;
            int dy=hit.slot==1?-22:hit.slot>=2?-11:0;
            int x=anchor.x+dx+(int)Math.round(hit.style.offsetX*hit.progress(cycle))-hit.image.getWidth()/2;
            int y=anchor.y-12+dy-(int)Math.round(hit.style.offsetY*hit.progress(cycle))-hit.image.getHeight();
            g.setComposite(AlphaComposite.SrcOver.derive(hit.alpha(cycle)));g.drawImage(hit.image,x,y,null);
        }
        g.setComposite(AlphaComposite.SrcOver);
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.List;

/** Completed HUD data only: no Actor/Model/HitSplat or writable client arrays cross the handoff. */
final class HudSnapshot
{
    final long token,npcKey;
    final int cycle;
    final ActorHud player,npc;
    final HudAssets.HealthSkin skin;
    HudSnapshot(long token,int cycle,long npcKey,ActorHud player,ActorHud npc,HudAssets.HealthSkin skin)
    { this.token=token;this.cycle=cycle;this.npcKey=npcKey;this.player=player;this.npc=npc;this.skin=skin; }

    static final class ActorHud
    {
        final long key;
        final HudHealth health;
        final List<Hit> hits;
        ActorHud(long key,HudHealth health,List<Hit> hits)
        { this.key=key;this.health=health;this.hits=List.copyOf(hits); }
    }

    static final class Hit
    {
        final int type,amount,expires,slot;
        final HitsplatStyle style;
        final BufferedImage image;
        Hit(int type,int amount,int expires,int slot,HitsplatStyle style,BufferedImage image)
        { this.type=type;this.amount=amount;this.expires=expires;this.slot=slot;this.style=style;this.image=image; }
        boolean active(int cycle) { return expires-cycle>0; }
        boolean visible(int cycle) { int remaining=expires-cycle;return remaining>0 && remaining<=style.duration; }
        double progress(int cycle) { return Math.max(0,Math.min(1,1-(expires-cycle)/(double)style.duration)); }
        float alpha(int cycle)
        {
            if(!visible(cycle)) return 0;
            return style.fadeStart<0 || style.fadeStart>=style.duration?1:
                (float)Math.min(1,(expires-cycle)/(double)(style.duration-style.fadeStart));
        }
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.BooleanSupplier;

/** Client-thread identity/slot state; synchronized clear() may release references from the EDT. */
final class HudTracker
{
    private Object player, npc;
    private long playerSerial, npcKey = -1, generation;
    private final Slots playerSlots = new Slots(), npcSlots = new Slots();
    private HudHealth playerHealth = HudHealth.UNKNOWN, npcHealth = HudHealth.UNKNOWN;
    private boolean dirty = true;
    private HudSnapshot cached;

    synchronized long generation()
    {
        return generation;
    }

    /** Teardown cannot interleave identity binding and publication, or revive an old capture. */
    synchronized boolean inGeneration(long expected, Runnable update)
    {
        if (expected != generation) return false;
        update.run();
        return true;
    }

    /** Model capture also binds HUD identity and must not revive state after closing. */
    synchronized long selectPlayer(long expected, Object actor, BooleanSupplier current)
    {
        if (expected != generation || !current.getAsBoolean()) return -1;
        return selectPlayer(actor);
    }

    synchronized long selectPlayer(Object actor)
    {
        if (player != actor)
        {
            player = actor;
            playerSerial++;
            playerSlots.clear();
            playerHealth = HudHealth.UNKNOWN;
            dirty = true;
        }
        return playerSerial;
    }

    synchronized void selectNpc(Object actor, long key)
    {
        if (npc != actor || npcKey != key)
        {
            npc = actor;
            npcKey = actor == null ? -1 : key;
            npcSlots.clear();
            npcHealth = HudHealth.UNKNOWN;
            dirty = true;
        }
    }

    synchronized boolean add(Object actor, int type, int amount, int expires, int cycle,
        HitsplatStyle style, BufferedImage image)
    {
        if (actor == null || type < 0 || expires - cycle <= 0 || style == null || image == null) return false;
        Slots slots = actor == player ? playerSlots : actor == npc ? npcSlots : null;
        if (slots == null) return false;
        boolean added = slots.add(type, amount, expires, cycle, style, image);
        dirty |= added;
        return added;
    }

    synchronized HudSnapshot sample(long token, int cycle, HudHealth nextPlayer, HudHealth nextNpc,
        HudAssets.HealthSkin skin)
    {
        dirty |= playerSlots.expire(cycle) | npcSlots.expire(cycle);
        dirty |= !playerHealth.same(nextPlayer) || !npcHealth.same(nextNpc);
        playerHealth = nextPlayer;
        npcHealth = nextNpc;
        boolean ticking = playerSlots.any() || npcSlots.any();
        if (cached != null && !dirty && cached.token == token && cached.skin == skin
            && (!ticking || cached.cycle == cycle)) return cached;
        cached = new HudSnapshot(token, cycle, npcKey,
            new HudSnapshot.ActorHud(playerSerial, playerHealth, playerSlots.copy()),
            new HudSnapshot.ActorHud(npcKey, npcHealth, npcSlots.copy()), skin);
        dirty = false;
        return cached;
    }

    synchronized void clear()
    {
        generation++;
        player = null;
        npc = null;
        playerSerial++;
        npcKey = -1;
        playerSlots.clear();
        npcSlots.clear();
        playerHealth = npcHealth = HudHealth.UNKNOWN;
        cached = null;
        dirty = true;
    }

    private static final class Slots
    {
        private final HudSnapshot.Hit[] hits = new HudSnapshot.Hit[4];
        private int next;

        boolean add(int type, int amount, int expires, int cycle, HitsplatStyle style, BufferedImage image)
        {
            expire(cycle);
            int chosen = -1;
            for (int i = 0; i < hits.length; i++)
            {
                int slot = (next + i) % hits.length;
                if (hits[slot] == null)
                {
                    chosen = slot;
                    break;
                }
            }
            if (chosen < 0)
            {
                if (style.replaceMode != 0 && style.replaceMode != 1) return false;
                chosen = 0;
                for (int i = 1; i < hits.length; i++)
                {
                    boolean preferred = style.replaceMode == 1 ? hits[i].amount < hits[chosen].amount
                        : hits[i].expires - cycle < hits[chosen].expires - cycle;
                    if (preferred) chosen = i;
                }
                if (style.replaceMode == 1 && amount <= hits[chosen].amount) return false;
            }
            hits[chosen] = new HudSnapshot.Hit(type, amount, expires, chosen, style, image);
            next = (chosen + 1) % hits.length;
            return true;
        }

        boolean expire(int cycle)
        {
            boolean changed = false;
            for (int i = 0; i < hits.length; i++)
            {
                if (hits[i] != null && !hits[i].active(cycle))
                {
                    hits[i] = null;
                    changed = true;
                }
            }
            return changed;
        }

        boolean any()
        {
            for (HudSnapshot.Hit hit : hits) if (hit != null) return true;
            return false;
        }

        List<HudSnapshot.Hit> copy()
        {
            List<HudSnapshot.Hit> result = new ArrayList<>(4);
            for (HudSnapshot.Hit hit : hits) if (hit != null) result.add(hit);
            return result;
        }

        void clear()
        {
            Arrays.fill(hits, null);
            next = 0;
        }
    }
}

package com.modelpopout;

import java.util.concurrent.Executor;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

/** One replaceable packet and at most one queued/running EDT delivery, including racing offers. */
final class LatestHudMailbox
{
    private final AtomicReference<HudSnapshot> latest = new AtomicReference<>();
    private final AtomicBoolean queued = new AtomicBoolean();
    private final Executor dispatch;
    private final Consumer<HudSnapshot> receive;

    LatestHudMailbox(Executor dispatch, Consumer<HudSnapshot> receive)
    {
        this.dispatch = dispatch;
        this.receive = receive;
    }

    void offer(HudSnapshot packet)
    {
        latest.set(packet);
        schedule();
    }

    void clear()
    {
        latest.set(null);
    }

    private void schedule()
    {
        if (queued.compareAndSet(false, true)) dispatch.execute(this::drain);
    }

    private void drain()
    {
        try
        {
            HudSnapshot packet = latest.getAndSet(null);
            if (packet != null) receive.accept(packet);
        }
        finally
        {
            queued.set(false);
            if (latest.get() != null) schedule();
        }
    }
}

package com.modelpopout;

/** Short synchronized operations shared by the client thread and Swing EDT. */
final class LiveCaptureGate
{
    private long epoch;
    private boolean open, loggedIn, pending, scheduled;
    private long nextDue;
    private int fps = 20;

    synchronized void setRate(int fps)
    {
        this.fps = Math.max(1, Math.min(50, fps));
        scheduled = false;
    }

    synchronized long open()
    {
        open = true;
        invalidate();
        return epoch;
    }

    synchronized void close()
    {
        open = false;
        invalidate();
    }

    synchronized long setLoggedIn(boolean value)
    {
        if (loggedIn != value)
        {
            loggedIn = value;
            invalidate();
        }
        return epoch;
    }

    private void invalidate()
    {
        epoch++;
        pending = false;
        scheduled = false;
    }

    /** Returns a lifecycle ticket, or -1 if throttled, inactive, or awaiting an EDT handoff. */
    synchronized long acquire(long now, boolean force)
    {
        if (!open || !loggedIn || pending) return -1;
        if (!force && scheduled && now - nextDue < 0) return -1;
        long period = 1_000_000_000L / fps;
        if (force || !scheduled)
        {
            nextDue = now + period;
        }
        else
        {
            // Keep fractional tick timing at 20 FPS (50ms) on a 20ms tick cadence.
            // Skip missed deadlines rather than scheduling catch-up captures.
            nextDue = now + period - (now - nextDue) % period;
        }
        scheduled = true;
        pending = true;
        return epoch;
    }

    synchronized boolean complete(long ticket)
    {
        if (ticket != epoch || !open || !loggedIn) return false;
        pending = false;
        return true;
    }

    synchronized boolean current(long ticket)
    {
        return open && ticket == epoch;
    }

    synchronized boolean viewing()
    {
        return open;
    }

    synchronized boolean active()
    {
        return open && loggedIn;
    }

    synchronized long epoch()
    {
        return epoch;
    }
}

package com.modelpopout;

/** EDT-confined latest model/view state: one active render and one replaceable latest request. */
final class LiveViewState
{
    private ModelSnapshot model;
    private TextureSet textures = TextureSet.EMPTY;
    private double texturePhase;
    private ModelFrame framing;
    private ModelSnapshot npcModel;
    private ModelFrame npcFraming;
    private long npcKey = -1, sceneSession;
    private boolean npcEnabled;
    private CameraView camera = CameraView.DEFAULT;
    private long revision, modelSession, attemptedRevision = -1;
    private RenderRequest active;

    boolean updateModel(ModelSnapshot next, boolean force)
    {
        if (!force && next.sameAppearance(model)) return false;
        if (framing == null) framing = ModelFrame.initial(next);
        model = next;
        revision++;
        return true;
    }

    boolean updateNpc(ModelSnapshot next, long key)
    {
        if (!npcEnabled) { next = null; key = -1; }
        boolean identityChanged = key != npcKey;
        boolean visibilityChanged = (next != null) != (npcModel != null);
        if (!identityChanged && !visibilityChanged && (next == null || next.sameAppearance(npcModel))) return false;
        if (identityChanged || visibilityChanged) sceneSession++;
        if (identityChanged) npcFraming = null;
        if (next != null && npcFraming == null) npcFraming = ModelFrame.initial(next);
        npcKey = key;
        npcModel = next;
        revision++;
        return true;
    }

    boolean removeNpc(long key)
    {
        return npcKey == key && updateNpc(null, -1);
    }

    void setNpcEnabled(boolean enabled)
    {
        if (npcEnabled == enabled) return;
        npcEnabled = enabled;
        if (!enabled) { npcModel = null; npcFraming = null; npcKey = -1; }
        sceneSession++;
        revision++;
    }

    boolean npcEnabled() { return npcEnabled; }
    boolean hasNpc() { return npcEnabled && npcModel != null; }
    long npcKey() { return npcKey; }

    CameraView camera()
    {
        return camera;
    }

    void setCamera(CameraView next)
    {
        if (camera.yaw == next.yaw && camera.pitch == next.pitch && camera.zoom == next.zoom) return;
        camera = next;
        revision++;
    }

    boolean updateTextures(TextureSet next)
    {
        if (next.samePixels(textures)) return false;
        textures = next;
        revision++;
        return true;
    }

    boolean hasAnimatedTextures() { return textures.animated(); }

    void setTexturePhase(double phase)
    {
        double quantized = Math.floor(phase*1024)/1024;
        if (textures.animated() && quantized != texturePhase) { texturePhase = quantized; revision++; }
    }

    boolean needsRender() { return active == null && model != null && revision != attemptedRevision; }

    RenderRequest begin()
    {
        if (active != null || model == null || revision == attemptedRevision) return null;
        active = new RenderRequest(model, camera, framing, revision, modelSession,
            npcEnabled, npcModel, npcFraming, npcKey, sceneSession,textures,texturePhase);
        return active;
    }

    boolean finish(RenderRequest request)
    {
        if (active != request) return false;
        active = null;
        attemptedRevision = request.revision;
        return valid(request);
    }

    boolean valid(RenderRequest request)
    {
        return request.modelSession == modelSession && request.sceneSession == sceneSession;
    }

    void clear()
    {
        model = null;
        textures = TextureSet.EMPTY;
        texturePhase = 0;
        npcModel = null; npcFraming = null; npcKey = -1;
        sceneSession++;
        modelSession++;
        revision++;
        // Keep the active slot occupied until the real worker ends, including across close/reopen.
    }

    void resetFraming()
    {
        clear();
        framing = null;
    }

    static final class RenderRequest
    {
        final TextureSet textures;
        final double texturePhase;
        final ModelSnapshot model;
        final CameraView camera;
        final ModelFrame framing, npcFraming;
        final ModelSnapshot npcModel;
        final boolean npcEnabled;
        final long npcKey;
        private final long revision, modelSession, sceneSession;
        private RenderRequest(ModelSnapshot model, CameraView camera, ModelFrame framing, long revision, long modelSession,
            boolean npcEnabled, ModelSnapshot npcModel, ModelFrame npcFraming, long npcKey, long sceneSession,TextureSet textures,double texturePhase)
        {
            this.textures = textures; this.texturePhase = texturePhase;
            this.model = model;
            this.camera = camera;
            this.framing = framing;
            this.revision = revision;
            this.modelSession = modelSession;
            this.npcEnabled = npcEnabled; this.npcModel = npcModel; this.npcFraming = npcFraming;
            this.npcKey = npcKey; this.sceneSession = sceneSession;
        }
    }
}

package com.modelpopout;

/** Immutable model-space framing, established once and independent of animation pose. */
final class ModelFrame
{
    // Reserve motion space even when the first sample is a crouched/compact pose.
    private static final double MIN_ANIMATION_RADIUS = 256;
    private static final double ANIMATION_HEADROOM = 2;
    final double centerX, centerY, centerZ, radius;

    private ModelFrame(double centerX, double centerY, double centerZ, double radius)
    {
        this.centerX = centerX;
        this.centerY = centerY;
        this.centerZ = centerZ;
        this.radius = radius;
    }

    static ModelFrame initial(ModelSnapshot mesh)
    {
        ModelFrame fitted = fit(mesh);
        return new ModelFrame(fitted.centerX, fitted.centerY, fitted.centerZ,
            Math.max(MIN_ANIMATION_RADIUS, fitted.radius * ANIMATION_HEADROOM));
    }

    /** Tight framing for isolated static renderer tests; live frames use initial() once. */
    static ModelFrame fit(ModelSnapshot mesh)
    {
        double minX = Double.POSITIVE_INFINITY, minY = minX, minZ = minX;
        double maxX = Double.NEGATIVE_INFINITY, maxY = maxX, maxZ = maxX;
        for (int i = 0; i < mesh.x.length; i++)
        {
            minX = Math.min(minX, mesh.x[i]); maxX = Math.max(maxX, mesh.x[i]);
            minY = Math.min(minY, mesh.y[i]); maxY = Math.max(maxY, mesh.y[i]);
            minZ = Math.min(minZ, mesh.z[i]); maxZ = Math.max(maxZ, mesh.z[i]);
        }
        double cx = (minX + maxX) / 2, cy = (minY + maxY) / 2, cz = (minZ + maxZ) / 2;
        double radius = 0;
        for (int i = 0; i < mesh.x.length; i++)
        {
            double x = mesh.x[i] - cx, y = mesh.y[i] - cy, z = mesh.z[i] - cz;
            radius = Math.max(radius, Math.sqrt(x * x + y * y + z * z));
        }
        return new ModelFrame(cx, cy, cz, Math.max(.5, radius));
    }

    double scale(CameraView camera)
    {
        return (ModelRenderer.SIZE - 48) / (2 * radius) * camera.zoom;
    }
}

