        navigation = null;
        SwingUtilities.invokeLater(() -> {
            renderWake.stop(); presentWake.stop(); metricsWake.stop();
            if (window != null) window.dispose();
            if (settingsNavigation != null) toolbar.removeNavigation(settingsNavigation);
            settingsNavigation = null; settingsPanel = null;
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!ModelPopoutConfig.GROUP.equals(event.getGroup())) return;
        if ("refreshRate".equals(event.getKey())) captures.setRate(config.refreshRate());
        if (ModelPopoutConfig.NPC_KEY.equals(event.getKey())) npcTargets.clear();
        SwingUtilities.invokeLater(() -> {
            if (settingsPanel != null) settingsPanel.sync(config);
            if ("renderTarget".equals(event.getKey()))
            {
                pacer.setTarget(config.renderTarget());
                requestRender();
            }
            if (window == null) return;
            if (ModelPopoutConfig.HITSPLATS_KEY.equals(event.getKey()) || ModelPopoutConfig.HP_BARS_KEY.equals(event.getKey())) panel.repaint();
            if (ModelPopoutConfig.ALWAYS_ON_TOP_KEY.equals(event.getKey())) applyWindowStacking();
            if (ModelPopoutConfig.OPACITY_KEY.equals(event.getKey())) window.applyBackgroundOpacity(config.backgroundOpacity());
            if (ModelPopoutConfig.NPC_KEY.equals(event.getKey()))
            {
                viewState.setNpcEnabled(config.renderNpc());
                panel.setPreferredSize(new Dimension(ModelRenderer.SIZE * (config.renderNpc() ? 2 : 1),ModelRenderer.SIZE));
                panel.repaint();
                requestRender();
            }
        });
    }

    @Subscribe
    public void onInteractingChanged(InteractingChanged event)
    {
        if (running && captures.viewing() && config.renderNpc()) npcTargets.interaction(event.getSource(),event.getTarget());
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        if (running && captures.viewing() && config.renderNpc()) npcTargets.spawned(event.getNpc());
    }

    @Subscribe
    public void onNpcChanged(NpcChanged event)
    {
        if (running && captures.viewing() && config.renderNpc()) npcTargets.spawned(event.getNpc());
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        long key = npcTargets.despawned(event.getNpc());
        if (key < 0) return;
        hudTracker.selectNpc(null,-1);
        long token = captures.epoch();
        SwingUtilities.invokeLater(() -> {
            if (current(token) && viewState.removeNpc(key))
            {
                panel.repaint();
                requestRender();
            }
        });
    }

    @Subscribe
    public void onPostClientTick(PostClientTick event)
    {
        samplePlayer();
        sampleTextures();
        sampleHud();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        boolean loggedIn = event.getGameState() == GameState.LOGGED_IN;
        long token = captures.setLoggedIn(loggedIn);
        if (loggedIn) return;
        textureReferences = null; clientTextures = TextureSet.EMPTY;
        npcTargets.clear();
        hudTracker.clear(); hudMailbox.clear(); clientHud = null;
        SwingUtilities.invokeLater(() -> {
            if (current(token))
            {
                clearModel();
            }
        });
    }

    private void openWindow()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (!running) return;
        if (window != null)
        {
            window.revealControls();
            window.setExtendedState(window.getExtendedState() & ~java.awt.Frame.ICONIFIED);
            window.setVisible(true);
            window.toFront();
            return;
        }
        ViewerWindow frame = ViewerWindow.create();
        window = frame;
        viewerVisible = true;
        frame.addWindowStateListener(e -> {
            viewerVisible = (e.getNewState() & java.awt.Frame.ICONIFIED) == 0;
            if (viewerVisible)
            {
                // Refresh the game-cycle HUD before showing hits retained while minimized.
                hudMailbox.clear();
                if (panel != null) panel.hud = null;
                clientHud = null;
                clientThread.invokeLater(this::sampleHud);
                requestRender();
            }
        });
        frame.setDefaultCloseOperation(JFrame.DISPOSE_ON_CLOSE);
        frame.setResizable(true);
        captures.open();
        pacer.setTarget(config.renderTarget());
        renderWake.setRepeats(false); presentWake.setRepeats(false);
        performance.sample(System.nanoTime()); metricsWake.start();
        viewState.resetFraming();
        viewState.setCamera(CameraView.DEFAULT);
        viewState.setNpcEnabled(config.renderNpc());
        panel = new ModelPanel(config);
        frame.add(panel, java.awt.BorderLayout.CENTER);
        frame.addWindowListener(new WindowAdapter()
        {
            @Override public void windowClosed(WindowEvent event)
            {
                if (window != frame) return;
                captures.close();
                viewerVisible = false; textureReferences = null; clientTextures = TextureSet.EMPTY;
                renderWake.stop(); presentWake.stop(); metricsWake.stop();
                pendingFrame = null;
                if (settingsPanel != null) settingsPanel.showPerformance("Viewer closed — capture and rendering stopped.");
                npcTargets.clear();
                clearModel();
                window = null; panel = null;
            }
        });
        ModelPanel modelPanel = panel;
        frame.setModelPainter(g -> {
            Graphics2D modelGraphics = (Graphics2D) g.create(modelPanel.getX(),modelPanel.getY(),modelPanel.getWidth(),modelPanel.getHeight());
            try { modelPanel.paintModels(modelGraphics); }
            finally { modelGraphics.dispose(); }
        });
        frame.setPresentationListener(() -> { if (modelPanel.image != null) performance.presented(); });
        frame.installHoverControls();
        frame.applyBackgroundOpacity(config.backgroundOpacity());
        applyWindowStacking();
        frame.setMinimumSize(new Dimension(480, 300));
        frame.pack();
        frame.setLocationByPlatform(true);
        frame.setVisible(true);
        clientThread.invokeLater(() -> { samplePlayer(); sampleTextures(); sampleHud(); });
    }

    private void applyWindowStacking()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (!window.applyAlwaysOnTop(config.alwaysOnTop()))
            LOG.debug("Desktop did not accept the Model Popout Always on Top setting");
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (diagnosticNoHud || !running || !viewerVisible || !captures.active()) return;
        assert client.isClientThread();
        long generation = hudTracker.generation(), token = captures.epoch();
        Player player = client.getLocalPlayer();
        if (player == null) return;
        // A first hit can precede the next throttled model capture for a newly selected target.
        NpcTargetTracker.Selection selected = event.getActor() instanceof NPC && config.renderNpc()
            ? npcTargets.select(player,token) : npcTargets.currentSelection();
        Actor actor = event.getActor();
        if (actor == null || (actor != player && (!config.renderNpc() || actor != selected.npc))) return;
        Hitsplat hit = event.getHitsplat();
        if (hit == null || hit.getHitsplatType() < 0) return;
        try
        {
            HitsplatStyle style = hudAssets.style(hit.getHitsplatType());
            if (style == null) return;
            int type = hit.getHitsplatType(), amount = hit.getAmount(), expiry = hit.getDisappearsOnGameCycle();
            int cycle = client.getGameCycle();
            BufferedImage image = hudAssets.hitImage(type,style,amount);
            hudTracker.inGeneration(generation,() -> {
                if (!running || !captures.active() || !captures.current(token)) return;
                hudTracker.selectPlayer(player);
                hudTracker.selectNpc(config.renderNpc()?selected.npc:null,config.renderNpc()?selected.key:-1);
                hudTracker.add(actor,type,amount,expiry,cycle,style,image);
            });
        }
        catch (RuntimeException unavailable) { LOG.debug("Unable to capture hitsplat visuals",unavailable); }
    }

    /** Independent native-cycle HUD updates: never schedules a 3D rendering job. */
    private void sampleHud()
    {
        if (diagnosticNoHud || !running || !viewerVisible || !captures.active()) return;
        assert client.isClientThread();
        if (client.getGameState() != GameState.LOGGED_IN) return;
        long generation = hudTracker.generation(), token = captures.epoch();
        try
        {
            Player player = client.getLocalPlayer();
            NpcTargetTracker.Selection selected = npcTargets.currentSelection();
            NPC npc = config.renderNpc()?selected.npc:null;
            HudHealth playerHealth = player == null ? HudHealth.UNKNOWN : HudHealth.player(player.getHealthRatio(),player.getHealthScale(),
                client.getBoostedSkillLevel(Skill.HITPOINTS),client.getRealSkillLevel(Skill.HITPOINTS));
            HudHealth npcHealth = npc == null ? HudHealth.UNKNOWN : HudHealth.scaled(npc.getHealthRatio(),npc.getHealthScale());
            int cycle = client.getGameCycle();
            HudAssets.HealthSkin skin = hudAssets.healthSkin(cycle);
            hudTracker.inGeneration(generation,() -> {
                if (!running || !captures.active() || !captures.current(token)) return;
                hudTracker.selectPlayer(player);
                hudTracker.selectNpc(npc,npc==null?-1:selected.key);
                HudSnapshot next = hudTracker.sample(token,cycle,playerHealth,npcHealth,skin);
                if (next != clientHud) { clientHud = next; hudMailbox.offer(next); }
            });
        }
        catch (RuntimeException unavailable) { LOG.debug("Unable to sample combat HUD",unavailable); }
    }

    private void receiveHud(HudSnapshot next)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (!current(next.token) || panel == null) return;
        panel.hud = next;
        if (playerTrace != null) playerTrace.record("hud","cycle="+next.cycle+" token="+next.token+" playerKey="+next.player.key+" npcKey="+next.npcKey);
        if (paintDiagnostics) hudDeliveries++;
        if (config.showHitsplats() || config.showHpBars()) panel.repaint();
    }

    /** Runs only on the client thread, including PostClientTick even when canvas drawing is slow. */
    private void samplePlayer()
    {
        if (!running || !viewerVisible || !captures.viewing()) return;
        assert client.isClientThread();
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
        captures.setLoggedIn(loggedIn);
        if (!loggedIn) return;
        long token = captures.acquire(System.nanoTime(), false);
        if (token < 0) return;
        long hudGeneration = hudTracker.generation();
        ModelSnapshot snapshot = null;
        ModelSnapshot npcSnapshot = null;
        long npcKey = -1;
        long playerHudKey = -1;
        try
        {
            Player player = client.getLocalPlayer();
            playerHudKey = hudTracker.selectPlayer(hudGeneration,player,() -> running && captures.current(token));
            Model model = player == null ? null : player.getModel();
            if (model != null)
            {
                snapshot = ModelSnapshot.capture(model, client.getTextureProvider());
                if (config.renderNpc())
                {
                    NpcTargetTracker.Selection selected = npcTargets.select(player,token);
                    NPC npc = selected.npc;
                    if (npc != null)
                    {
                        npcKey = selected.key;
                        try
                        {
                            Model npcModel = npc.getModel();
                            if (npcModel != null) npcSnapshot = ModelSnapshot.capture(npcModel,client.getTextureProvider());
                        }
                        catch (RuntimeException failure)
                        {
                            LOG.debug("Unable to capture NPC model",failure);
                        }
                    }
                }
            }
        }
        catch (RuntimeException failure)
        {
            LOG.debug("Unable to capture live player model", failure);
        }
        if (snapshot != null) textureReferences = new TextureReferences(snapshot,npcSnapshot);
        int sceneCycle = client.getGameCycle();
        long sceneObservedAt = System.nanoTime();
        TextureSet sampledTextures = clientTextures;
        try
        {
            if (snapshot != null) sampledTextures = TextureSet.capture(client.getTextureProvider(),snapshot,npcSnapshot,
                sceneCycle,client.isGpu(),clientTextures);
        }
        catch (RuntimeException failure) { LOG.debug("Unable to copy game textures; using captured default colors",failure); }
        clientTextures = sampledTextures;
        TextureSet textureCopy = sampledTextures;
        ModelSnapshot next = snapshot, nextNpc = npcSnapshot;
        long capturedPlayerHudKey = playerHudKey;
        long selectedNpcKey = npcKey;
        SwingUtilities.invokeLater(() -> {
            // Complete only the matching lifecycle ticket; old callbacks cannot unblock a new session.
            boolean accepted = captures.complete(token) && current(token);
            if (playerTrace != null) playerTrace.record("capture","accepted="+accepted+" token="+token+" playerKey="+capturedPlayerHudKey
                +" pose="+(next==null?"null":System.identityHashCode(next)+" vertices="+next.x.length+" faces="+next.a.length
                +" alphaHash="+java.util.Arrays.hashCode(next.alpha))+" npcKey="+selectedNpcKey);
            if (!accepted) return;
            if (next == null) { performance.capture(false); return; }
            // Compare copied geometry/colors, since native Model instances can be shared or reused.
            boolean playerIdentityChanged = panel.sourcePlayerHudKey != capturedPlayerHudKey;
            if (paintDiagnostics && playerIdentityChanged) playerRebindings++;
            panel.sourcePlayerHudKey = capturedPlayerHudKey;
            boolean changed = viewState.updateModel(next, playerIdentityChanged);
            changed |= viewState.updateNpc(nextNpc,selectedNpcKey);
            performance.capture(changed);
            changed |= viewState.updateTextures(textureCopy);
            textureClock.observe(sceneCycle,sceneObservedAt);
            if (changed)
            {
                requestRender();
            }
        });
    }

    /** Texture clocks/pixels are sampled independently of the geometry capture throttle. */
    private void sampleTextures()
    {
        assert client.isClientThread();
        if (!running || !viewerVisible || !captures.active()) return;
        TextureReferences refs = textureReferences;
        if (refs == null || !refs.textured() || !texturePending.compareAndSet(false,true)) return;
        long token = captures.epoch();
        int observedCycle = client.getGameCycle();
        long observedAt = System.nanoTime();
        TextureSet sampled = clientTextures;
        try
        {
            sampled = TextureSet.capture(client.getTextureProvider(),refs.player,refs.npc,
                observedCycle,client.isGpu(),clientTextures);
        }
        catch (RuntimeException failure) { LOG.debug("Unable to update texture pixels; retaining the previous material data",failure); }
        TextureSet copy = sampled;
        clientTextures = copy;
        SwingUtilities.invokeLater(() -> {
            texturePending.set(false);
            if (!current(token)) return;
            viewState.updateTextures(copy);
            textureClock.observe(observedCycle,observedAt);
            requestRender();
        });
    }

    private static final class TextureReferences
    {
        final ModelSnapshot player,npc;
        TextureReferences(ModelSnapshot player,ModelSnapshot npc) { this.player = player; this.npc = npc; }
        boolean textured()
        {
            for (ModelSnapshot mesh : new ModelSnapshot[]{player,npc})
                if (mesh != null && mesh.textureIds != null) for (short id : mesh.textureIds) if (id >= 0) return true;
            return false;
        }
    }

    private boolean current(long token)
    {
        return running && window != null && captures.current(token);
    }

    private void requestRender()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (!running || !viewerVisible || window == null || !captures.active() || worker != null) return;
        long now = System.nanoTime();
        if (viewState.hasAnimatedTextures()) viewState.setTexturePhase(textureClock.phase(now));
        if (!viewState.needsRender())
        {
            if (viewState.hasAnimatedTextures() && textureClock.advancing(now))
            { renderWake.setInitialDelay(FramePacer.delayMillis(pacer.renderDelay(now))); renderWake.restart(); }
            return;
        }
        long delay = pacer.renderDelay(System.nanoTime());
        if (delay > 0) { renderWake.setInitialDelay(FramePacer.delayMillis(delay)); renderWake.restart(); return; }
        LiveViewState.RenderRequest request = viewState.begin();
        if (request == null) return;
        long token = captures.epoch();
        pacer.rendered(System.nanoTime());
        RenderJob job = new RenderJob(request,token,panel.sourcePlayerHudKey);
        worker = job;
        if (playerTrace != null) playerTrace.record("render-start","job="+System.identityHashCode(job)+" token="+token+" pose="+System.identityHashCode(request.model)+" playerKey="+job.playerHudKey);
        try
        {
            renderExecutor.execute(() -> {
                BufferedImage image = null;
                Throwable failure = null;
                try { image = new ModelRenderer().renderScene(request); }
                catch (Throwable error) { failure = error; }
                if (playerTrace != null) playerTrace.record("render-complete","job="+System.identityHashCode(job)+" error="+(failure!=null)+" "+PlayerFrameTrace.pixels(image));
                BufferedImage completed = image;
                Throwable error = failure;
                // SwingWorker.done batches callbacks at ~33ms; an explicit EDT handoff avoids that cap.
                SwingUtilities.invokeLater(() -> finishRender(job,completed,error));
            });
        }
        catch (RejectedExecutionException failure) { finishRender(job,null,failure); }
    }

    private void finishRender(RenderJob job, BufferedImage image, Throwable error)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (worker != job) return;
        worker = null;
        boolean valid = viewState.finish(job.request);
        if (playerTrace != null) playerTrace.record("render-accept","job="+System.identityHashCode(job)+" valid="+valid+" current="+current(job.token));
        if (error != null) LOG.debug("Unable to render live view",error);
        else
        {
            boolean newTextureFrame = job.request.textures.animated()
                && (job.request.texturePhase != measuredTexturePhase || job.request.textures != measuredTextures);
            performance.rendered(newTextureFrame);
            measuredTexturePhase = job.request.texturePhase; measuredTextures = job.request.textures;
            if (valid && current(job.token))
            {
                pendingFrame = new CompletedFrame(image,job.request,job.token,job.playerHudKey);
                presentFrame();
            }
        }
        requestRender();
    }

    private void presentFrame()
    {
        assert SwingUtilities.isEventDispatchThread();
        if (pendingFrame == null) return;
        if (!current(pendingFrame.token) || !viewState.valid(pendingFrame.request)) { if (playerTrace != null) playerTrace.record("discard","stale completed frame; displayed image retained"); pendingFrame = null; return; }
        long delay = pacer.presentationDelay(System.nanoTime());
        if (delay > 0) { presentWake.setInitialDelay(FramePacer.delayMillis(delay)); presentWake.restart(); return; }
        CompletedFrame next = pendingFrame;
        pendingFrame = null;
        if (diagnosticFreeze && panel.image != null)
        {
            if (playerTrace != null) playerTrace.record("hold","completed image retained for isolation A");
            pacer.presented(System.nanoTime());
            return;
        }
        if (playerTrace != null) playerTrace.record("publish","old="+System.identityHashCode(panel.image)+" next="+System.identityHashCode(next.image)+" token="+next.token+" playerKey="+next.playerHudKey);
        if (panel.imagePlayerHudKey != next.playerHudKey || panel.playerHudAnchor == null)
            panel.playerHudAnchor = HudAnchor.initial(next.request.model,next.request.framing);
        if (next.request.npcModel == null) panel.npcHudAnchor = null;
        else if (panel.imageNpcKey != next.request.npcKey || panel.npcHudAnchor == null)
            panel.npcHudAnchor = HudAnchor.initial(next.request.npcModel,next.request.npcFraming);
        panel.imagePlayerHudKey = next.playerHudKey;
        panel.imageNpcKey = next.request.npcKey;
        panel.imageCamera = next.request.camera;
        panel.image = next.image;
        if (paintDiagnostics) modelPublications++;
        panel.imageNpcEnabled = next.request.npcEnabled;
        panel.mirrorNpc = ModelScenePainter.shouldMirrorNpc(next.request.camera);
        pacer.presented(System.nanoTime());
        window.getContentPane().repaint();
    }

    private static final class RenderJob
    {
        final LiveViewState.RenderRequest request;
        final long token,playerHudKey;
        RenderJob(LiveViewState.RenderRequest request, long token,long playerHudKey)
        { this.request = request; this.token = token; this.playerHudKey = playerHudKey; }
    }

    private static final class CompletedFrame
    {
        final BufferedImage image;
        final LiveViewState.RenderRequest request;
        final long token,playerHudKey;
        CompletedFrame(BufferedImage image, LiveViewState.RenderRequest request, long token,long playerHudKey)
        { this.image = image; this.request = request; this.token = token; this.playerHudKey = playerHudKey; }
    }

    private void clearModel()
    {
        if (playerTrace != null) playerTrace.record("clear","running="+running+" visible="+viewerVisible+" active="+captures.active()+" old="+System.identityHashCode(panel==null?null:panel.image));
        // Invalidate results, but keep a running worker's slot until it actually finishes.
        // SwingWorker.cancel(false) can call done() while its rendering code is still running.
        viewState.clear();
        textureClock.clear();
        hudTracker.clear(); hudMailbox.clear(); clientHud = null;
        pendingFrame = null; presentWake.stop(); renderWake.stop();
        if (panel != null)
        {
            panel.image = null; panel.hud = null;
            panel.playerHudAnchor = null; panel.npcHudAnchor = null;
            panel.sourcePlayerHudKey = panel.imagePlayerHudKey = panel.imageNpcKey = -1;
            panel.repaint();
        }
    }

    private static BufferedImage settingsIcon()
    {
        BufferedImage image = new BufferedImage(24,24,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            g.setColor(new Color(0xe2c36b));
            for (int y = 5; y <= 19; y += 7) g.fillRect(3,y,18,2);
            g.fillRect(7,2,3,8); g.fillRect(15,9,3,8); g.fillRect(10,16,3,7);
        }
        finally { g.dispose(); }
        return image;
    }

    private static BufferedImage icon()
    {
        BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try
        {
            g.setColor(new Color(0xe2c36b));
            g.fillOval(9, 2, 6, 6);
            g.fillRect(7, 9, 10, 8);
            g.fillRect(7, 17, 4, 6);
            g.fillRect(13, 17, 4, 6);
        }
        finally { g.dispose(); }
        return image;
    }

    final class ModelPanel extends JPanel
    {
        private BufferedImage image;
        private HudSnapshot hud;
        private HudAnchor playerHudAnchor,npcHudAnchor;
        private CameraView imageCamera = CameraView.DEFAULT;
        private long sourcePlayerHudKey = -1,imagePlayerHudKey = -1,imageNpcKey = -1;
        private boolean imageNpcEnabled;
        private boolean mirrorNpc;
        ModelPanel(ModelPopoutConfig initialConfig)
        {
            setPreferredSize(new Dimension(ModelRenderer.SIZE * (initialConfig.renderNpc() ? 2 : 1),ModelRenderer.SIZE));
            setOpaque(false);
            setDoubleBuffered(false);
            MouseAdapter controls = new MouseAdapter()
            {
                private Point previous;
                @Override public void mousePressed(MouseEvent event)
                {
                    if (SwingUtilities.isLeftMouseButton(event)) previous = event.getPoint();
                }
                @Override public void mouseReleased(MouseEvent event)
                {
                    if (SwingUtilities.isLeftMouseButton(event)) previous = null;
                }
                @Override public void mouseDragged(MouseEvent event)
                {
                    if (previous == null || (event.getModifiersEx() & MouseEvent.BUTTON1_DOWN_MASK) == 0) return;
                    viewState.setCamera(viewState.camera().drag(event.getX() - previous.x, event.getY() - previous.y));
                    previous = event.getPoint();
                    requestRender();
                }
                @Override public void mouseWheelMoved(MouseWheelEvent event)
                {
                    viewState.setCamera(viewState.camera().wheel(event.getPreciseWheelRotation()));
                    requestRender();
                }
            };
            addMouseListener(controls);
            addMouseMotionListener(controls);
            addMouseWheelListener(controls);
        }
        @Override public void repaint(long delay,int x,int y,int width,int height)
        {
            // HUD changes must invalidate the same whole compositing surface as model publication.
            // A child-only dirty rectangle otherwise creates a separate, clipped native update.
            java.awt.Container parent = getParent();
            if (width > 0 && height > 0 && parent instanceof ViewerWindow.Surface) parent.repaint(delay);
            else super.repaint(delay,x,y,width,height);
        }

        @Override protected void paintComponent(Graphics graphics) {}

        private void paintModels(Graphics graphics)
        {
            if (paintDiagnostics)
            {
                modelDraws++;
                if (window != null && !window.isPaintingWindow()) drawsOutsideWindowPaint++;
            }
            boolean tracePaint = playerTrace != null && System.nanoTime()-tracePaintAt >= 250_000_000L;
            String before = tracePaint ? PlayerFrameTrace.pixels(image) : null;
            ModelScenePainter.paint((Graphics2D) graphics,image,imageNpcEnabled,mirrorNpc,getWidth(),getHeight());
            if (image != null && !diagnosticNoHud)
                HudPainter.paint((Graphics2D)graphics,hud,playerHudAnchor,npcHudAnchor,imageCamera,getWidth(),getHeight(),
                    imageNpcEnabled,mirrorNpc,imagePlayerHudKey,viewState.hasNpc()?imageNpcKey:-1,config.showHitsplats(),config.showHpBars());
            if (tracePaint)
            {
                tracePaintAt = System.nanoTime();
                String after = PlayerFrameTrace.pixels(image);
                playerTrace.record("paint","window="+(window!=null&&window.isPaintingWindow())+" playerKey="+imagePlayerHudKey
                    +" sourceKey="+sourcePlayerHudKey+" hudCycle="+(hud==null?-1:hud.cycle)+" viewport="+getWidth()+"x"+getHeight()
                    +" unchanged="+before.equals(after)+" "+after);
            }
        }
    }
}

package com.modelpopout;

/** Cached projection and UVs. Texture-only updates do not recapture, convert or reproject geometry. */
final class ModelProjection
{
    final CameraView camera;
    final ModelFrame frame;
    final double[] x,y,z,uv;
    final int[] faces;
    private TextureRasterPlan rasterPlan;
    private boolean rasterAttempted;
    ModelProjection(ModelSnapshot mesh,CameraView camera,ModelFrame frame)
    {
        this.camera=camera; this.frame=frame;
        int n=mesh.x.length; x=new double[n]; y=new double[n]; z=new double[n];
        double scale=frame.scale(camera), cy=Math.cos(camera.yaw), sy=Math.sin(camera.yaw);
        double cp=Math.cos(camera.pitch), sp=Math.sin(camera.pitch);
        for(int i=0;i<n;i++)
        {
            double mx=mesh.x[i]-frame.centerX, my=mesh.y[i]-frame.centerY, mz=mesh.z[i]-frame.centerZ;
            double rx=mx*cy+mz*sy, rz=mz*cy-mx*sy;
            x[i]=ModelRenderer.SIZE/2.0+rx*scale;
            y[i]=ModelRenderer.SIZE/2.0+(my*cp-rz*sp)*scale;
            z[i]=my*sp+rz*cp;
        }
        uv=mesh.uvs(); faces=FaceOrdering.order(mesh,z);
    }
    TextureRasterPlan rasterPlan(ModelSnapshot mesh)
    {
        if (!rasterAttempted) { rasterPlan = TextureRasterPlan.build(mesh,this); rasterAttempted = true; }
        return rasterPlan;
    }

    boolean matches(CameraView view,ModelFrame reference)
    {
        return frame == reference && camera.yaw == view.yaw && camera.pitch == view.pitch && camera.zoom == view.zoom;
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;

/** Small orthographic CPU renderer. No RuneLite access or global rasterizer state. */
final class ModelRenderer
{
    static final int BACKGROUND = 0x20242a;
    static final int SIZE = 512;

    /** Single-snapshot helpers for static renderer checks; live rendering requires retained framing. */
    BufferedImage renderStatic(ModelSnapshot mesh)
    {
        return renderStatic(mesh, CameraView.DEFAULT);
    }

    BufferedImage renderStatic(ModelSnapshot mesh, CameraView camera)
    {
        return BackgroundOpacity.compose(render(mesh, camera, ModelFrame.fit(mesh)), 100);
    }

    BufferedImage render(ModelSnapshot mesh, CameraView camera, ModelFrame frame)
    {
        return render(mesh,camera,frame,TextureSet.EMPTY,0);
    }

    BufferedImage render(ModelSnapshot mesh,CameraView camera,ModelFrame frame,TextureSet textures,double phase)
    {
        ModelSnapshot rgb = mesh.toRgb();
        boolean textured = rgb.textureIds != null && java.util.stream.IntStream.range(0,rgb.textureIds.length).anyMatch(i -> rgb.textureIds[i] >= 0);
        TextureSet relevant = textured ? textures : TextureSet.EMPTY;
        double time = textured ? phase : 0;
        BufferedImage cached = rgb.cachedImage(camera,frame,relevant,time);
        if (cached != null) return cached;
        BufferedImage image = renderRgb(rgb,camera,frame,relevant,time);
        rgb.rememberImage(camera,frame,image,relevant,time);
        return image;
    }

    BufferedImage renderScene(LiveViewState.RenderRequest request)
    {
        BufferedImage player = render(request.model,request.camera,request.framing,request.textures,request.texturePhase);
        if (!request.npcEnabled) return player;
        BufferedImage scene = new BufferedImage(SIZE * 2, SIZE, BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = scene.createGraphics();
        try
        {
            g.drawImage(player, 0, 0, null);
            if (request.npcModel != null)
            {
                BufferedImage npc = render(request.npcModel,request.camera,request.npcFraming,request.textures,request.texturePhase);
                g.drawImage(npc, SIZE, 0, null);
            }
        }
        finally { g.dispose(); }
        return scene;
    }

    private BufferedImage renderRgb(ModelSnapshot mesh, CameraView camera, ModelFrame frame,TextureSet textures,double phase)
    {
        ModelProjection projection = mesh.projection(camera,frame);
        TextureRasterPlan plan = projection.rasterPlan(mesh);
        if (plan != null) return plan.render(textures,phase);
        return rasterize(mesh,projection,textures,phase);
    }

    // The uncached path also serves as the regression oracle for the bounded texture raster cache.
    BufferedImage rasterize(ModelSnapshot mesh,ModelProjection projection,TextureSet textures,double phase)
    {
        BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
        int[] pixels = ((DataBufferInt) image.getRaster().getDataBuffer()).getData();
        double[] depth = new double[pixels.length];
        Arrays.fill(depth, Double.POSITIVE_INFINITY);
        long remainingWork = 16000000;
        // Opaque depth first. Transparent faces test against it but never overwrite it.
        for (int pass=0;pass<2;pass++) for (int face : projection.faces)
        {
            int alpha = mesh.alpha[face] & 255;
            if (mesh.colorC[face] < 0 || alpha == 255 || ((alpha == 0) != (pass == 0))) continue;
            remainingWork -= triangle(mesh,face,projection.x,projection.y,projection.z,pixels,depth,remainingWork,projection.uv,textures,phase);
        }
        return image;
    }

    private int triangle(ModelSnapshot m, int face, double[] x, double[] y, double[] z,
        int[] pixels, double[] depth, long remainingWork,double[] uv,TextureSet textures,double phase)
    {
        int a = m.a[face], b = m.b[face], c = m.c[face];
        double area = edge(x[a], y[a], x[b], y[b], x[c], y[c]);
        // Native software rendering rejects reverse-wound faces. Cape backs occupy
        // the same surface as their textured fronts and must not enter the depth test.
        if (area <= 1e-8) return 0;
        int minX = Math.max(0, (int) Math.floor(Math.min(x[a], Math.min(x[b], x[c]))));
        int maxX = Math.min(SIZE - 1, (int) Math.ceil(Math.max(x[a], Math.max(x[b], x[c]))));
        int minY = Math.max(0, (int) Math.floor(Math.min(y[a], Math.min(y[b], y[c]))));
        int maxY = Math.min(SIZE - 1, (int) Math.ceil(Math.max(y[a], Math.max(y[b], y[c]))));
        int work = Math.max(0, maxX - minX + 1) * Math.max(0, maxY - minY + 1);
        if (work > remainingWork) throw new IllegalArgumentException("Model exceeds the rendering work limit");
        int transparency = m.alpha[face] & 255;
        double sourceAlpha = 1-transparency/255.0;
        int textureId = m.textureIds == null ? -1 : m.textureIds[face];
        TextureSet.Pixels texture = textures.texture(textureId);
        int uvOffset = face*6;
        boolean textured = texture != null && Double.isFinite(uv[uvOffset]);
        for (int py = minY; py <= maxY; py++)
        {
            for (int px = minX; px <= maxX; px++)
            {
                double wa = edge(x[b], y[b], x[c], y[c], px + .5, py + .5) / area;
                double wb = edge(x[c], y[c], x[a], y[a], px + .5, py + .5) / area;
                double wc = 1 - wa - wb;
                if (wa < -1e-9 || wb < -1e-9 || wc < -1e-9) continue;
                double dz = wa * z[a] + wb * z[b] + wc * z[c];
                int index = py * SIZE + px;
                if (dz >= depth[index]) continue;
                int texel = 0;
                double light = 1;
                if (textured)
                {
                    double u = wa*uv[uvOffset]+wb*uv[uvOffset+2]+wc*uv[uvOffset+4];
                    double v = wa*uv[uvOffset+1]+wb*uv[uvOffset+3]+wc*uv[uvOffset+5];
                    texel = texture.sampleArgb(u,v,phase,textures);
                    if (texel == 0) continue; // Native zero texels are cutouts, not black paint.
                    light = Math.max(0,(wa*m.lightA[face]+wb*m.lightB[face]+wc*m.lightC[face])/127.0);
                }
                double pixelAlpha = sourceAlpha*(textured ? (texel>>>24)/255.0 : 1);
                double destAlpha = (pixels[index]>>>24)/255.0;
                double outAlpha = pixelAlpha+destAlpha*(1-pixelAlpha);
                int rgb = (int) Math.round(outAlpha * 255) << 24;
                for (int shift = 0; shift <= 16; shift += 8)
                {
                    int value = (int) Math.round(wa * ((m.colorA[face] >> shift) & 255)
                        + wb * ((m.colorB[face] >> shift) & 255)
                        + wc * ((m.colorC[face] >> shift) & 255));
                    if (textured) value = (int)Math.round(((texel >> shift) & 255)*light);
                    if (pixelAlpha < 1) value = (int)Math.round((value*pixelAlpha
                        + ((pixels[index]>>shift)&255)*destAlpha*(1-pixelAlpha))/outAlpha);
                    rgb |= Math.max(0, Math.min(255, value)) << shift;
                }
                pixels[index] = rgb;
                if (transparency == 0) depth[index] = dz;
            }
        }
        return work;
    }

    private static double edge(double ax, double ay, double bx, double by, double px, double py)
    {
        return (px - ax) * (by - ay) - (py - ay) * (bx - ax);
    }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/** Display-only transforms of a completed scene; never modifies its pixels or game models. */
final class ModelScenePainter
{
    static boolean shouldMirrorNpc(CameraView camera)
    {
        // Native forward is -Z: its screen X is -sin(yaw). The right-hand NPC should face left.
        return Math.sin(camera.yaw) < -1e-9;
    }

    static void paint(Graphics2D graphics, BufferedImage image, boolean npcEnabled, boolean mirrorNpc,
        int width, int height)
    {
        if (image == null) return;
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setComposite(AlphaComposite.SrcOver);
            int slots = npcEnabled ? 2 : 1;
            int size = Math.min(width / slots,height);
            int x = (width - size * slots) / 2, y = (height - size) / 2;
            int sourceSize = ModelRenderer.SIZE;
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(image,x,y,x+size,y+size,0,0,sourceSize,sourceSize,null);
            if (slots == 2 && image.getWidth() >= sourceSize * 2)
                g.drawImage(image,x+size,y,x+size*2,y+size,
                    mirrorNpc ? sourceSize*2 : sourceSize,0,
                    mirrorNpc ? sourceSize : sourceSize*2,sourceSize,null);
        }
        finally { g.dispose(); }
    }
}

package com.modelpopout;

import java.util.Arrays;
import java.awt.image.BufferedImage;
import net.runelite.api.Model;
import net.runelite.api.TextureProvider;

/** Owned arrays only: never retain a client Model across threads or frames. */
final class ModelSnapshot
{
    final float[] x, y, z;
    final int[] a, b, c, colorA, colorB, colorC;
    final byte[] alpha;
    final short[] textureIds;
    final byte[] textureFaces, priorities;
    final int[] texA, texB, texC, lightA, lightB, lightC;
    final double brightness;
    private volatile double[] uv;
    private volatile ModelProjection projection;
    private final boolean packedColors;
    private volatile ModelSnapshot rgb;
    private volatile Rendered rendered;

    ModelSnapshot(float[] x, float[] y, float[] z, int[] a, int[] b, int[] c,
        int[] colorA, int[] colorB, int[] colorC, byte[] alpha)
    {
        this(x.clone(), y.clone(), z.clone(), a.clone(), b.clone(), c.clone(),
            colorA.clone(), colorB.clone(), colorC.clone(), alpha.clone(), false, null,null,null,null,null,null,null,null,null,.8);
    }

    private ModelSnapshot(float[] x, float[] y, float[] z, int[] a, int[] b, int[] c,
        int[] colorA, int[] colorB, int[] colorC, byte[] alpha, boolean packedColors,
        short[] textureIds, byte[] textureFaces, int[] texA, int[] texB, int[] texC,
        byte[] priorities, int[] lightA, int[] lightB, int[] lightC, double brightness)
    {
        this.packedColors = packedColors;
        this.x = x; this.y = y; this.z = z;
        this.a = a; this.b = b; this.c = c;
        this.colorA = colorA; this.colorB = colorB; this.colorC = colorC;
        this.alpha = alpha;
        this.textureIds = textureIds; this.textureFaces = textureFaces;
        this.texA = texA; this.texB = texB; this.texC = texC; this.priorities = priorities;
        this.lightA = lightA; this.lightB = lightB; this.lightC = lightC; this.brightness = brightness;
    }

    /** Must be called on the client thread. Does not mutate any client array. */
    static ModelSnapshot capture(Model model, TextureProvider textures)
    {
        int vertices = model.getVerticesCount(), faces = model.getFaceCount();
        if (vertices < 1 || vertices > 50000 || faces < 1 || faces > 30000)
        {
            throw new IllegalArgumentException("Model exceeds the snapshot size limit");
        }
        float[] x = copyRequired(model.getVerticesX(), vertices);
        float[] y = copyRequired(model.getVerticesY(), vertices);
        float[] z = copyRequired(model.getVerticesZ(), vertices);
        int[] a = copyRequired(model.getFaceIndices1(), faces);
        int[] b = copyRequired(model.getFaceIndices2(), faces);
        int[] c = copyRequired(model.getFaceIndices3(), faces);
        int[] ca = copyRequired(model.getFaceColors1(), faces);
        int[] cb = copyRequired(model.getFaceColors2(), faces);
        int[] cc = copyRequired(model.getFaceColors3(), faces);
        byte[] transparencies = copyOptional(model.getFaceTransparencies(), faces);
        byte[] alpha = transparencies == null ? new byte[faces] : transparencies;
        short[] faceTextures = copyOptional(model.getFaceTextures(), faces);
        byte[] textureFaces = copyOptional(model.getTextureFaces(), faces);
        int[] texA = copy(model.getTexIndices1()), texB = copy(model.getTexIndices2()), texC = copy(model.getTexIndices3());
        if (texA != null && (texB == null || texC == null || texA.length != texB.length || texA.length != texC.length))
            throw new IllegalArgumentException("Invalid texture mapping arrays");
        byte[] priorities = copyOptional(model.getFaceRenderPriorities(), faces);
        int[] lightA = ca.clone(), lightB = cb.clone(), lightC = cc.clone();
        int modelAlpha = model.getTransparency() & 255;
        byte override = model.getOverrideAmount();
        byte overrideHue=override==0 ? -1 : model.getOverrideHue();
        byte overrideSat=override==0 ? -1 : model.getOverrideSaturation();
        byte overrideLum=override==0 ? -1 : model.getOverrideLuminance();
        double brightness = textures == null ? .8 : textures.getBrightness();
        for (int i = 0; i < vertices; i++)
        {
            if (!Float.isFinite(x[i]) || !Float.isFinite(y[i]) || !Float.isFinite(z[i]))
            {
                throw new IllegalArgumentException("Non-finite player model vertex");
            }
        }
        for (int i = 0; i < faces; i++)
        {
            if (a[i] < 0 || a[i] >= vertices || b[i] < 0 || b[i] >= vertices || c[i] < 0 || c[i] >= vertices)
            {
                throw new IllegalArgumentException("Invalid player model face");
            }
            if (cc[i] == -2) // Native hidden-face sentinel.
            {
                ca[i] = cb[i] = cc[i] = -1;
                continue;
            }
            int faceAlpha = alpha[i] & 255;
            if (modelAlpha == 255) alpha[i] = (byte)255;
            else if (modelAlpha > 0 && faceAlpha < 253) alpha[i] = (byte)(faceAlpha + ((253-faceAlpha)*modelAlpha >> 8));
            boolean flat = cc[i] == -1;
            if (flat) lightB[i] = lightC[i] = lightA[i];
            if (faceTextures != null && faceTextures[i] != -1 && textures != null)
            {
                // Textured face colors are lighting intensities, not packed HSL.
                // Use the texture provider's fallback HSL; no texture cache loads.
                int base = textures.getDefaultColor(faceTextures[i] & 0xffff);
                ca[i] = shadeTexture(base, ca[i]);
                cb[i] = flat ? ca[i] : shadeTexture(base, cb[i]);
                cc[i] = flat ? ca[i] : shadeTexture(base, cc[i]);
            }
            else
            {
                cb[i] = flat ? ca[i] : cb[i];
                cc[i] = flat ? ca[i] : cc[i];
                if ((faceTextures == null || faceTextures[i] == -1) && override > 0)
                {
                    ca[i] = overrideHsl(ca[i],overrideHue,overrideSat,overrideLum,override);
                    cb[i] = overrideHsl(cb[i],overrideHue,overrideSat,overrideLum,override);
                    cc[i] = overrideHsl(cc[i],overrideHue,overrideSat,overrideLum,override);
                }
            }
        }
        return new ModelSnapshot(x,y,z,a,b,c,ca,cb,cc,alpha,true,faceTextures,textureFaces,texA,texB,texC,priorities,lightA,lightB,lightC,brightness);
    }

    /** Exact array comparison, not Model identity or an animation-ID-only heuristic. */
    boolean sameAppearance(ModelSnapshot other)
    {
        return other != null && packedColors == other.packedColors
            && Arrays.equals(x, other.x) && Arrays.equals(y, other.y) && Arrays.equals(z, other.z)
            && Arrays.equals(a, other.a) && Arrays.equals(b, other.b) && Arrays.equals(c, other.c)
            && Arrays.equals(colorA, other.colorA) && Arrays.equals(colorB, other.colorB)
            && Arrays.equals(colorC, other.colorC) && Arrays.equals(alpha, other.alpha)
            && Arrays.equals(textureIds,other.textureIds) && Arrays.equals(textureFaces,other.textureFaces)
            && Arrays.equals(texA,other.texA) && Arrays.equals(texB,other.texB) && Arrays.equals(texC,other.texC)
            && Arrays.equals(priorities,other.priorities) && Arrays.equals(lightA,other.lightA)
            && Arrays.equals(lightB,other.lightB) && Arrays.equals(lightC,other.lightC) && brightness == other.brightness;
    }

    /** Palette work runs on the render worker, cached for subsequent camera-only renders. */
    ModelSnapshot toRgb()
    {
        if (!packedColors) return this;
        ModelSnapshot cached = rgb;
        if (cached != null) return cached;
        int[] ca = colorA.clone(), cb = colorB.clone(), cc = colorC.clone();
        for (int i = 0; i < ca.length; i++)
        {
            if (cc[i] < 0) continue;
            ca[i] = hslToRgb(ca[i],brightness);
            cb[i] = hslToRgb(cb[i],brightness);
            cc[i] = hslToRgb(cc[i],brightness);
        }
        cached = new ModelSnapshot(x,y,z,a,b,c,ca,cb,cc,alpha,false,textureIds,textureFaces,texA,texB,texC,priorities,lightA,lightB,lightC,brightness);
        rgb = cached;
        return cached;
    }

    /** One bounded raster cache per owned pose; unchanged actors need not reraster for the other actor. */
    BufferedImage cachedImage(CameraView camera, ModelFrame frame, TextureSet textures, double phase)
    {
        Rendered cached = rendered;
        return cached != null && cached.frame == frame && cached.yaw == camera.yaw
            && cached.pitch == camera.pitch && cached.zoom == camera.zoom
            && cached.textures == textures && cached.phase == phase ? cached.image : null;
    }

    void rememberImage(CameraView camera,ModelFrame frame,BufferedImage image,TextureSet textures,double phase)
    {
        rendered = new Rendered(camera,frame,image,textures,phase);
    }

    private static final class Rendered
    {
        final ModelFrame frame;
        final double yaw, pitch, zoom, phase;
        final TextureSet textures;
        final BufferedImage image;
        Rendered(CameraView camera, ModelFrame frame, BufferedImage image,TextureSet textures,double phase)
        {
            this.textures = textures; this.phase = phase;
            this.frame = frame; yaw = camera.yaw; pitch = camera.pitch; zoom = camera.zoom; this.image = image;
        }
    }

    ModelProjection projection(CameraView camera, ModelFrame frame)
    {
        ModelProjection cached = projection;
        if (cached == null || !cached.matches(camera,frame)) projection = cached = new ModelProjection(this,camera,frame);
        return cached;
    }

    double[] uvs()
    {
        double[] cached = uv;
        if (cached == null) uv = cached = TextureCoordinates.compute(this);
        return cached;
    }

    private static float[] copyRequired(float[] values, int count)
    {
        if (values == null || values.length < count) throw new IllegalArgumentException("Incomplete model vertex arrays");
        return Arrays.copyOf(values, count);
    }

    private static int[] copyRequired(int[] values, int count)
    {
        if (values == null || values.length < count) throw new IllegalArgumentException("Incomplete model face arrays");
        return Arrays.copyOf(values, count);
    }

    private static byte[] copyOptional(byte[] values, int count)
    {
        if (values == null) return null;
        if (values.length < count) throw new IllegalArgumentException("Incomplete model face metadata");
        return Arrays.copyOf(values, count);
    }

    private static short[] copyOptional(short[] values, int count)
    {
        if (values == null) return null;
        if (values.length < count) throw new IllegalArgumentException("Incomplete model texture assignments");
        return Arrays.copyOf(values, count);
    }

    private static int[] copy(int[] values)
    {
        if (values == null) return null;
        if (values.length > 50000) throw new IllegalArgumentException("Texture mapping limit exceeded");
        return values.clone();
    }

    private static int overrideHsl(int hsl, byte hue, byte saturation, byte luminance, byte amount)
    {
        int[] components = {hsl>>10 & 63,hsl>>7 & 7,hsl & 127};
        int[] target = {hue,saturation,luminance};
        for (int i=0;i<3;i++) if (target[i] != -1) components[i] += ((amount & 255)*(target[i]-components[i]))>>7;
        return ((components[0]<<10) | (components[1]<<7) | components[2]) & 65535;
    }

    private static int shadeTexture(int hsl, int light)
    {
        return (hsl & 0xff80) | Math.max(2, Math.min(126, (hsl & 127) * light / 128));
    }

    static int hslToRgb(int packed) { return hslToRgb(packed,.8); }

    static int hslToRgb(int packed, double brightness)
    {
        double h = ((packed >> 10) & 63) / 64.0 + 1.0 / 128;
        double s = ((packed >> 7) & 7) / 8.0 + 1.0 / 16;
        double l = (packed & 127) / 128.0;
        double q = l < .5 ? l * (1 + s) : l + s - l * s;
        double p = 2 * l - q;
        return channel(hue(p, q, h + 1.0 / 3),brightness) << 16
            | channel(hue(p, q, h),brightness) << 8 | channel(hue(p, q, h - 1.0 / 3),brightness);
    }

    private static double hue(double p, double q, double t)
    {
        t -= Math.floor(t);
        if (t < 1.0 / 6) return p + (q - p) * 6 * t;
        if (t < .5) return q;
        if (t < 2.0 / 3) return p + (q - p) * (2.0 / 3 - t) * 6;
        return p;
    }

    private static int channel(double value,double brightness)
    {
        return Math.max(0, Math.min(255, (int) (Math.pow(value, brightness) * 256)));
    }
}

package com.modelpopout;

/** Selection policy over copied relationship flags; identity, not reused NPC slot numbers, wins. */
final class NpcSelector
{
    static final class Candidate<T>
    {
        final T npc;
        final int index;
        final boolean present, attacking, dead, combat, deathAnimating;
        Candidate(T npc, int index, boolean present, boolean attacking, boolean dead, boolean combat)
        {
            this(npc,index,present,attacking,dead,combat,dead);
        }
        Candidate(T npc, int index, boolean present, boolean attacking, boolean dead, boolean combat, boolean deathAnimating)
        {
            this.deathAnimating = deathAnimating;
            this.npc = npc; this.index = index; this.present = present;
            this.attacking = attacking; this.dead = dead; this.combat = combat;
        }
    }

    static <T> T select(T direct, T previous, Iterable<Candidate<T>> candidates)
    {
        Candidate<T> old = null, fallback = null;
        for (Candidate<T> candidate : candidates)
        {
            if (!candidate.present || (candidate.dead && !candidate.deathAnimating)) continue;
            if (candidate.npc == direct) return direct;
            if (candidate.npc == previous) old = candidate;
            if (candidate.attacking && candidate.combat && !candidate.dead
                && (fallback == null || candidate.index < fallback.index)) fallback = candidate;
        }
        // Keep the selected NPC only while its actual death action is running, or until despawn.
        // A new explicit player target always takes precedence above.
        if (old != null && (old.dead || (old.attacking && old.combat))) return previous;
        return fallback == null ? null : fallback.npc;
    }
}

