package com.modelpopout;

/** Observe native cycles; fractional texture motion may advance at most one 20ms cycle ahead. */
final class TextureClock
{
    private int cycle;
    private long observedAt;
    private boolean observed;
    void observe(int next, long now)
    {
        if (!observed || next != cycle) { cycle = next; observedAt = now; observed = true; }
    }
    double phase(long now)
    {
        return observed ? cycle + Math.max(0,Math.min(1,(now-observedAt)/20_000_000.0)) : 0;
    }
    boolean advancing(long now) { return observed && now-observedAt < 20_000_000L; }
    void clear() { observed = false; }
}

package com.modelpopout;

/** Recover the game's planar UV basis from copied texture-mapping triangles, using a Gram solve. */
final class TextureCoordinates
{
    static double[] compute(ModelSnapshot mesh)
    {
        double[] uv = new double[mesh.a.length*6];
        for (int face = 0; face < mesh.a.length; face++)
        {
            int offset = face*6;
            if (mesh.textureFaces == null || mesh.textureFaces[face] == -1)
            {
                uv[offset+2] = 1; uv[offset+5] = 1;
                continue;
            }
            int mapping = mesh.textureFaces[face] & 255;
            if (mesh.texA == null || mapping >= mesh.texA.length)
            { invalid(uv,offset); continue; }
            int origin = mesh.texA[mapping], b = mesh.texB[mapping], c = mesh.texC[mapping];
            if (origin < 0 || b < 0 || c < 0 || origin >= mesh.x.length || b >= mesh.x.length || c >= mesh.x.length)
            { invalid(uv,offset); continue; }
            double[] e = {mesh.x[b]-mesh.x[origin],mesh.y[b]-mesh.y[origin],mesh.z[b]-mesh.z[origin]};
            double[] f = {mesh.x[c]-mesh.x[origin],mesh.y[c]-mesh.y[origin],mesh.z[c]-mesh.z[origin]};
            double ee = dot(e,e), ff = dot(f,f), ef = dot(e,f), determinant = ee*ff-ef*ef;
            if (Math.abs(determinant) < 1e-12) { invalid(uv,offset); continue; }
            int[] vertices = {mesh.a[face],mesh.b[face],mesh.c[face]};
            for (int vertex = 0; vertex < 3; vertex++)
            {
                int index = vertices[vertex];
                double[] p = {mesh.x[index]-mesh.x[origin],mesh.y[index]-mesh.y[origin],mesh.z[index]-mesh.z[origin]};
                double pe = dot(p,e), pf = dot(p,f);
                uv[offset+vertex*2] = (pe*ff-pf*ef)/determinant;
                uv[offset+vertex*2+1] = (pf*ee-pe*ef)/determinant;
            }
        }
        return uv;
    }
    private static double dot(double[] a,double[] b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }
    private static void invalid(double[] uv,int offset) { for (int i=0;i<6;i++) uv[offset+i] = Double.NaN; }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.awt.image.DataBufferInt;
import java.util.Arrays;

/** Bounded opaque-model raster cache: reuse static pixels and texture coverage/UVs on texture-only frames. */
final class TextureRasterPlan
{
    static final int MAX_FRAGMENTS = 65536;
    private final int[] base,baseRank,workingRank;
    private final double[] baseDepth;
    private final double[] workingDepth;
    private final int[] pixel,material,fallback,rank;
    private final double[] depth,u,v,light;
    private final int count;
    private final int[] usedMaterials;
    private final ModelSnapshot mesh;
    private final ModelProjection projection;

    private TextureRasterPlan(Builder b,ModelSnapshot mesh,ModelProjection projection)
    {
        this.mesh=mesh;this.projection=projection;
        usedMaterials=java.util.stream.IntStream.range(0,mesh.textureIds.length).map(i -> mesh.textureIds[i]).filter(id -> id>=0).distinct().toArray();
        base=b.base; baseRank=b.baseRank;workingRank=new int[base.length];baseDepth=b.baseDepth; workingDepth=new double[baseDepth.length]; count=b.count;
        rank=Arrays.copyOf(b.rank,count);pixel=Arrays.copyOf(b.pixel,count); material=Arrays.copyOf(b.material,count); fallback=Arrays.copyOf(b.fallback,count);
        depth=Arrays.copyOf(b.depth,count);u=Arrays.copyOf(b.u,count);v=Arrays.copyOf(b.v,count);light=Arrays.copyOf(b.light,count);
    }

    static TextureRasterPlan build(ModelSnapshot mesh,ModelProjection projection)
    {
        if (mesh.textureIds == null) return null;
        boolean texturedFace=false;
        for(int face=0;face<mesh.textureIds.length;face++) if(mesh.textureIds[face]>=0 && Double.isFinite(projection.uv[face*6])) { texturedFace=true;break; }
        if(!texturedFace) return null;
        for (byte alpha : mesh.alpha) if ((alpha&255) != 0 && (alpha&255) != 255) return null;
        Builder builder=new Builder();
        long work=0;
        int[] ranks=new int[mesh.a.length];
        for(int i=0;i<projection.faces.length;i++) ranks[projection.faces[i]]=i;
        for(int pass=0;pass<2;pass++) for(int face:projection.faces)
        {
            if(mesh.colorC[face]<0 || (mesh.alpha[face]&255)==255) continue;
            int uvOffset=face*6;
            boolean textured=mesh.textureIds[face]>=0 && Double.isFinite(projection.uv[uvOffset]);
            if(textured != (pass==1)) continue;
            int a=mesh.a[face],b=mesh.b[face],c=mesh.c[face];
            double area=edge(projection.x[a],projection.y[a],projection.x[b],projection.y[b],projection.x[c],projection.y[c]);
            // Match the general/native path before caching any face coverage.
            if(area<=1e-8) continue;
            int minX=Math.max(0,(int)Math.floor(Math.min(projection.x[a],Math.min(projection.x[b],projection.x[c]))));
            int maxX=Math.min(511,(int)Math.ceil(Math.max(projection.x[a],Math.max(projection.x[b],projection.x[c]))));
            int minY=Math.max(0,(int)Math.floor(Math.min(projection.y[a],Math.min(projection.y[b],projection.y[c]))));
            int maxY=Math.min(511,(int)Math.ceil(Math.max(projection.y[a],Math.max(projection.y[b],projection.y[c]))));
            work+=(long)Math.max(0,maxX-minX+1)*Math.max(0,maxY-minY+1);
            if(work>16000000) return null; // Full renderer preserves the existing work-limit rejection.
            for(int py=minY;py<=maxY;py++) for(int px=minX;px<=maxX;px++)
            {
                double wa=edge(projection.x[b],projection.y[b],projection.x[c],projection.y[c],px+.5,py+.5)/area;
                double wb=edge(projection.x[c],projection.y[c],projection.x[a],projection.y[a],px+.5,py+.5)/area;
                double wc=1-wa-wb;
                if(wa < -1e-9 || wb < -1e-9 || wc < -1e-9) continue;
                int index=py*512+px;
                double z=wa*projection.z[a]+wb*projection.z[b]+wc*projection.z[c];
                if(z>builder.baseDepth[index] || (z==builder.baseDepth[index] && ranks[face]>=builder.baseRank[index])) continue;
                int color=0xff000000;
                for(int shift=0;shift<=16;shift+=8) color|=(int)Math.round(wa*((mesh.colorA[face]>>shift)&255)
                    +wb*((mesh.colorB[face]>>shift)&255)+wc*((mesh.colorC[face]>>shift)&255))<<shift;
                if(!textured) { builder.base[index]=color; builder.baseDepth[index]=z;builder.baseRank[index]=ranks[face]; continue; }
                if(builder.count==MAX_FRAGMENTS) return null;
                builder.ensureCapacity();
                int i=builder.count++;
                builder.rank[i]=ranks[face];builder.pixel[i]=index;builder.material[i]=mesh.textureIds[face];builder.depth[i]=z;builder.fallback[i]=color;
                builder.u[i]=wa*projection.uv[uvOffset]+wb*projection.uv[uvOffset+2]+wc*projection.uv[uvOffset+4];
                builder.v[i]=wa*projection.uv[uvOffset+1]+wb*projection.uv[uvOffset+3]+wc*projection.uv[uvOffset+5];
                builder.light[i]=Math.max(0,(wa*mesh.lightA[face]+wb*mesh.lightB[face]+wc*mesh.lightC[face])/127.0);
            }
        }
        return builder.count==0 ? null : new TextureRasterPlan(builder,mesh,projection);
    }

    BufferedImage render(TextureSet textures,double phase)
    {
        // Filtered moving cutouts create partial alpha; preserve exact priority/depth blending via the general path.
        for(int id:usedMaterials)
        {
            TextureSet.Pixels texture=textures.texture(id);
            if(texture!=null && texture.moving && texture.cutouts) return new ModelRenderer().rasterize(mesh,projection,textures,phase);
        }
        BufferedImage image=new BufferedImage(512,512,BufferedImage.TYPE_INT_ARGB);
        int[] pixels=((DataBufferInt)image.getRaster().getDataBuffer()).getData();
        System.arraycopy(base,0,pixels,0,base.length);
        double[] z=workingDepth;
        System.arraycopy(baseDepth,0,z,0,baseDepth.length);
        System.arraycopy(baseRank,0,workingRank,0,baseRank.length);
        for(int i=0;i<count;i++)
        {
            int index=pixel[i];
            if(depth[i]>z[index] || (depth[i]==z[index] && rank[i]>=workingRank[index])) continue;
            TextureSet.Pixels texture=textures.texture(material[i]);
            int color=texture==null ? fallback[i] : PixelBlend.shade(texture.sampleArgb(u[i],v[i],phase,textures),light[i]);
            if((color>>>24)==0) continue;
            pixels[index]=PixelBlend.over(color,pixels[index]);z[index]=depth[i];workingRank[index]=rank[i];
        }
        return image;
    }
    int fragments() { return count; }

    private static double edge(double ax,double ay,double bx,double by,double px,double py)
    { return (px-ax)*(by-ay)-(py-ay)*(bx-ax); }

    private static final class Builder
    {
        int count;
        final int[] base=new int[512*512],baseRank=new int[512*512];
        final double[] baseDepth=new double[512*512];
        int[] rank=new int[2048],pixel=new int[2048],material=new int[2048],fallback=new int[2048];
        double[] depth=new double[2048],u=new double[2048],v=new double[2048],light=new double[2048];
        Builder() { Arrays.fill(baseDepth,Double.POSITIVE_INFINITY);Arrays.fill(baseRank,Integer.MAX_VALUE); }
        void ensureCapacity()
        {
            if(count<pixel.length) return;
            int next=Math.min(MAX_FRAGMENTS,pixel.length*2);
            rank=Arrays.copyOf(rank,next);pixel=Arrays.copyOf(pixel,next);material=Arrays.copyOf(material,next);fallback=Arrays.copyOf(fallback,next);
            depth=Arrays.copyOf(depth,next);u=Arrays.copyOf(u,next);v=Arrays.copyOf(v,next);light=Arrays.copyOf(light,next);
        }
    }
}

package com.modelpopout;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import java.util.Map;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;

/** Immutable copies of referenced game textures. Native cache reads happen only on the client thread. */
final class TextureSet
{
    static final TextureSet EMPTY = new TextureSet(Collections.emptyMap(),0,false);
    final Map<Integer, Pixels> textures;
    private final Pixels[] byId;
    final int cycle;
    final boolean gpu;
    TextureSet(Map<Integer, Pixels> textures, int cycle, boolean gpu)
    {
        this.textures = Collections.unmodifiableMap(new HashMap<>(textures));
        int maximum = -1;
        for (int id : textures.keySet()) if (id >= 0 && id <= 32767) maximum = Math.max(maximum,id);
        byId = new Pixels[maximum+1];
        for (Map.Entry<Integer,Pixels> entry : textures.entrySet()) if (entry.getKey() >= 0 && entry.getKey() < byId.length) byId[entry.getKey()] = entry.getValue();
        this.cycle = cycle; this.gpu = gpu;
    }

    static TextureSet capture(TextureProvider provider, ModelSnapshot player, ModelSnapshot npc,
        int cycle, boolean gpu)
    {
        return capture(provider,player,npc,cycle,gpu,EMPTY);
    }

    static TextureSet capture(TextureProvider provider,ModelSnapshot player,ModelSnapshot npc,
        int cycle,boolean gpu,TextureSet previous)
    {
        if (provider == null) return previous;
        Map<Integer, Pixels> copied = new HashMap<>();
        Texture[] metadata = provider.getTextures();
        Set<Integer> visited = new HashSet<>();
        for (ModelSnapshot model : new ModelSnapshot[]{player,npc})
        {
            if (model == null || model.textureIds == null) continue;
            for (int face=0;face<model.textureIds.length;face++)
            {
                int id = model.textureIds[face];
                if (id < 0 || model.colorC[face] < 0 || (model.alpha[face]&255)==255 || visited.contains(id) || visited.size() >= 32) continue;
                visited.add(id);
                Pixels old = previous.textures.get(id);
                if (metadata == null || id >= metadata.length || metadata[id] == null)
                { if (old != null) copied.put(id,old); continue; }
                int[] pixels;
                try { pixels = provider.load(id); }
                catch (RuntimeException unavailable) { pixels = null; }
                if (pixels == null) { if (old != null) copied.put(id,old); continue; }
                Texture texture = metadata[id];
                int direction=texture.getAnimationDirection(),speed=texture.getAnimationSpeed();
                float u=texture.getU(),v=texture.getV();
                Pixels copy = old != null && previous.gpu==gpu && old.direction==direction && old.speed==speed && old.u==u && old.v==v
                    && Arrays.equals(old.rgb,pixels) ? old : new Pixels(pixels,direction,speed,u,v,cycle);
                if (copy.size > 0) copied.put(id,copy);
            }
        }
        return new TextureSet(copied,cycle,gpu);
    }

    Pixels texture(int id) { return id >= 0 && id < byId.length ? byId[id] : null; }

    boolean animated()
    {
        for (Pixels pixels : textures.values()) if (pixels.moving) return true;
        return false;
    }

    boolean samePixels(TextureSet other)
    {
        if (other == null || gpu != other.gpu || !textures.keySet().equals(other.textures.keySet())) return false;
        for (Map.Entry<Integer,Pixels> entry : textures.entrySet())
            if (!entry.getValue().same(other.textures.get(entry.getKey()))) return false;
        return true;
    }

    static final class Pixels
    {
        final int[] rgb;
        final int size, direction, speed, originCycle;
        final boolean anchored;
        final float u, v;
        final boolean moving,cutouts;
        Pixels(int[] rgb,int direction,int speed,float u,float v)
        { this(rgb,direction,speed,u,v,0,false); }
        Pixels(int[] rgb,int direction,int speed,float u,float v,int cycle)
        { this(rgb,direction,speed,u,v,cycle,true); }
        private Pixels(int[] rgb,int direction,int speed,float u,float v,int cycle,boolean anchored)
        {
            this.originCycle=cycle;this.anchored=anchored;
            int dimension = (int)Math.sqrt(rgb.length);
            size = dimension * dimension == rgb.length && dimension > 0 && dimension <= 256
                && (dimension & (dimension-1)) == 0 ? dimension : 0;
            this.rgb = size == 0 ? new int[0] : rgb.clone();
            this.direction = direction; this.speed = speed;
            this.u = Float.isFinite(u) ? u : 0; this.v = Float.isFinite(v) ? v : 0;
            boolean varied=false,clear=false;
            for (int pixel : this.rgb) { if (pixel != this.rgb[0]) varied=true; if (pixel == 0) clear=true; }
            cutouts=clear;
            moving=varied && direction>=1 && direction<=4 && speed>0;
        }
        boolean same(Pixels other)
        {
            return other != null && direction == other.direction && speed == other.speed
                && u == other.u && v == other.v && Arrays.equals(rgb,other.rgb);
        }
        int sampleArgb(double baseU,double baseV,double phase,TextureSet set)
        {
            double cycles = set.gpu ? phase : phase-(anchored ? originCycle : set.cycle);
            double unit = set.gpu ? 1.0/128 : 1.0/size;
            double uOffset = (direction == 2 ? -1 : direction == 4 ? 1 : 0)*speed*cycles*unit;
            double vOffset = (direction == 1 ? -1 : direction == 3 ? 1 : 0)*speed*cycles*unit;
            double u = baseU+this.u+uOffset, v = baseV+this.v+vOffset;
            u-=Math.floor(u);v-=Math.floor(v);
            if (direction < 1 || direction > 4 || speed == 0)
            {
                int pixel = sample(u,v);
                return pixel == 0 ? 0 : 0xff000000 | pixel;
            }
            // Linear filtering of real texels gives continuous scrolling, with premultiplied cutouts.
            double px=u*size-.5,py=v*size-.5;
            int x=(int)Math.floor(px),y=(int)Math.floor(py);
            double fx=px-x,fy=py-y;
            double alpha=0,r=0,g=0,b=0;
            for(int dy=0;dy<2;dy++) for(int dx=0;dx<2;dx++)
            {
                int pixel=rgb[((y+dy)&(size-1))*size+((x+dx)&(size-1))];
                double weight=(dx==0?1-fx:fx)*(dy==0?1-fy:fy);
                if(pixel==0) continue;
                alpha+=weight;r+=((pixel>>16)&255)*weight;g+=((pixel>>8)&255)*weight;b+=(pixel&255)*weight;
            }
            if(alpha<1e-9) return 0;
            return ((int)Math.round(alpha*255)<<24) | ((int)Math.round(r/alpha)<<16)
                | ((int)Math.round(g/alpha)<<8) | (int)Math.round(b/alpha);
        }

        int sample(double u, double v)
        {
            int x = (int)Math.floor(u*size), y = (int)Math.floor(v*size);
            return rgb[(y & (size-1))*size+(x & (size-1))];
        }
    }
}

package com.modelpopout;

import java.util.Locale;

/** Counts distinct work stages; presentation means completed Swing paints, not monitor refresh. */
final class ViewerPerformance
{
    private long captures, poses, renders, paints, textureFrames;
    private boolean sampled;
    private long captureBase, poseBase, renderBase, paintBase, textureBase, sampleTime;
    synchronized void capture(boolean unique) { captures++; if (unique) poses++; }
    synchronized void rendered(boolean texture) { renders++; if (texture) textureFrames++; }
    synchronized void presented() { paints++; }
    synchronized String sample(long now)
    {
        if (!sampled) { sampled = true; sampleTime = now; return "Waiting for measurements…"; }
        double seconds = Math.max(.001,(now-sampleTime)/1e9);
        String text = String.format(Locale.ROOT,
            "Capture %.1f/s · unique poses %.1f/s · completed renders %.1f/s · Swing paints %.1f/s · texture frames %.1f/s · viewer pose interpolation off",
            (captures-captureBase)/seconds,(poses-poseBase)/seconds,(renders-renderBase)/seconds,
            (paints-paintBase)/seconds,(textureFrames-textureBase)/seconds);
        captureBase = captures; poseBase = poses; renderBase = renders; paintBase = paints; textureBase = textureFrames; sampleTime = now;
        return text;
    }
}

package com.modelpopout;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.function.BiConsumer;
import javax.swing.JButton;
