import net.runelite.client.ui.PluginPanel;

/** Supported RuneLite sidebar UI; the slider writes the same persisted ConfigManager key. */
final class ViewerSettingsPanel extends PluginPanel
{
    final JSlider opacity = new JSlider(0,100);
    final JCheckBox hitsplats = new JCheckBox("Show Hitsplats");
    final JCheckBox hpBars = new JCheckBox("Show HP Bars");
    final JCheckBox alwaysOnTop = new JCheckBox("Always on Top");
    final JCheckBox npcs = new JCheckBox("Render interacting NPC");
    private final JSpinner rate = new JSpinner(new SpinnerNumberModel(20,1,50,1));
    final JComboBox<RenderTarget> renderTarget = new JComboBox<>(RenderTarget.values());
    private final JLabel performance = new JLabel();
    private final JLabel opacityLabel = new JLabel();
    private boolean updating;

    ViewerSettingsPanel(ModelPopoutConfig config, BiConsumer<String,Object> save, Runnable open)
    {
        setLayout(new BorderLayout(8,8));
        JPanel controls = new JPanel(new GridLayout(0,1,4,8));
        controls.add(new JLabel("Model Popout settings"));
        JButton launch = new JButton("Open Model Popout");
        launch.addActionListener(e -> open.run());
        controls.add(launch);
        controls.add(npcs);
        controls.add(alwaysOnTop);
        controls.add(hitsplats);
        controls.add(hpBars);
        controls.add(new JLabel("Model capture FPS"));
        controls.add(rate);
        controls.add(new JLabel("Rendering target"));
        controls.add(renderTarget);
        controls.add(performance);
        controls.add(opacityLabel);
        opacity.setMajorTickSpacing(25);
        opacity.setPaintTicks(true);
        opacity.setPaintLabels(true);
        controls.add(opacity);
        controls.add(new JLabel("<html>Native title bar opacity:<br>controlled by the desktop.</html>"));
        add(controls,BorderLayout.NORTH);
        opacity.addChangeListener(e -> {
            opacityLabel.setText("Background opacity: " + opacity.getValue() + "%");
            if (!updating) save.accept(ModelPopoutConfig.OPACITY_KEY,opacity.getValue());
        });
        hitsplats.addActionListener(e -> { if (!updating) save.accept(ModelPopoutConfig.HITSPLATS_KEY,hitsplats.isSelected()); });
        hpBars.addActionListener(e -> { if (!updating) save.accept(ModelPopoutConfig.HP_BARS_KEY,hpBars.isSelected()); });
        alwaysOnTop.addActionListener(e -> { if (!updating) save.accept(ModelPopoutConfig.ALWAYS_ON_TOP_KEY,alwaysOnTop.isSelected()); });
        npcs.addActionListener(e -> { if (!updating) save.accept(ModelPopoutConfig.NPC_KEY,npcs.isSelected()); });
        rate.addChangeListener(e -> { if (!updating) save.accept("refreshRate",rate.getValue()); });
        renderTarget.addActionListener(e -> { if (!updating) save.accept("renderTarget",renderTarget.getSelectedItem()); });
        sync(config);
    }

    void sync(ModelPopoutConfig config)
    {
        updating = true;
        try
        {
            opacity.setValue(BackgroundOpacity.clamp(config.backgroundOpacity()));
            opacityLabel.setText("Background opacity: " + opacity.getValue() + "%");
            hitsplats.setSelected(config.showHitsplats());
            hpBars.setSelected(config.showHpBars());
            alwaysOnTop.setSelected(config.alwaysOnTop());
            npcs.setSelected(config.renderNpc());
            renderTarget.setSelectedItem(config.renderTarget());
            rate.setValue(Math.max(1,Math.min(50,config.refreshRate())));
        }
        finally { updating = false; }
    }
    void showPerformance(String text)
    {
        performance.setText("<html>" + text.replace(" · ","<br>") + "</html>");
    }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Frame;
import java.awt.Rectangle;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.JRootPane;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import javax.swing.SwingUtilities;

/** Buffered per-pixel viewer with KDE/native window controls, edge resizing and opaque fallback. */
final class ViewerWindow extends JFrame
{
    private static final Logger LOG = LoggerFactory.getLogger(ViewerWindow.class);
    private final boolean translucentCreated;
    private final Surface surface = new Surface();
    private final WindowPresentation presentation = new WindowPresentation();
    private int requestedOpacity = 100;
    private boolean supported;
    private boolean paintingWindow;
    private Runnable presented = () -> {};

    static ViewerWindow create()
    {
        GraphicsDevice device = GraphicsEnvironment.getLocalGraphicsEnvironment().getDefaultScreenDevice();
        GraphicsConfiguration capable = null;
        if (device.isWindowTranslucencySupported(GraphicsDevice.WindowTranslucency.PERPIXEL_TRANSLUCENT))
        {
            for (GraphicsConfiguration gc : device.getConfigurations())
            {
                if (gc.isTranslucencyCapable()) { capable = gc; break; }
            }
        }
        ViewerWindow window = new ViewerWindow(capable == null ? device.getDefaultConfiguration() : capable,capable != null);
        if (capable != null)
        {
            try { window.setBackground(new Color(0,0,0,0)); }
            catch (UnsupportedOperationException | java.awt.IllegalComponentStateException failure)
            {
                window.dispose();
                window = new ViewerWindow(device.getDefaultConfiguration(),false);
            }
        }
        return window;
    }

    private ViewerWindow(GraphicsConfiguration configuration, boolean translucent)
    {
        super("Model Popout",configuration);
        translucentCreated = translucent;
        supported = translucent;
        setUndecorated(true);
        setContentPane(surface);
        keepPresentationNonOpaque(getRootPane());
        getRootPane().setDoubleBuffered(false);
        surface.setBorder(BorderFactory.createEmptyBorder(6,6,6,6));
        installResize(surface);
        addPropertyChangeListener("graphicsConfiguration",e -> SwingUtilities.invokeLater(() -> {
            if (Boolean.getBoolean("modelpopout.paintDiagnostics"))
                LOG.debug("Model Popout graphics configuration changed: old={} new={} displayable={}",e.getOldValue(),e.getNewValue(),isDisplayable());
            if (isDisplayable()) applyBackgroundOpacity(requestedOpacity);
        }));
    }

    void applyBackgroundOpacity(int requested)
    {
        requestedOpacity = BackgroundOpacity.clamp(requested);
        // A moved window may report the device's ordinary configuration. Window.setBackground
        // negotiates a capable configuration when needed; do not mistake that for lost support.
        supported = translucentCreated && getGraphicsConfiguration().getDevice().isWindowTranslucencySupported(GraphicsDevice.WindowTranslucency.PERPIXEL_TRANSLUCENT);
        if (Boolean.getBoolean("modelpopout.paintDiagnostics"))
            LOG.debug("Model Popout background policy: requested={} supported={} currentConfigurationCapable={}",requestedOpacity,supported,getGraphicsConfiguration().isTranslucencyCapable());
        supported = WindowTransparency.apply(supported,() -> getGraphicsConfiguration().isTranslucencyCapable(),
            this::getBackground,this::setBackground);
        surface.opacity = BackgroundOpacity.effective(requestedOpacity,supported);
        surface.setToolTipText(!supported && requestedOpacity < 100 ? "Desktop transparency unavailable; background stays opaque." : null);
        surface.repaint();
    }

    @Override public void setBackground(Color background)
    {
        Color previous = getBackground();
        try { super.setBackground(background); }
        finally
        {
            // Window.setBackground resets all three Swing layers to opaque on alpha 0 -> 255.
            // Even the native opaque fallback must ascend to ViewerWindow.paint, never paint
            // a Swing subtree directly into the native destination outside its private buffer.
            keepPresentationNonOpaque(getRootPane());
        }
        if (Boolean.getBoolean("modelpopout.paintDiagnostics") && previous != null
            && background != null && previous.getAlpha() != background.getAlpha())
            LOG.debug("Model Popout window background alpha: {} -> {}; presentation layers kept nonopaque",
                previous.getAlpha(),background.getAlpha(),new Throwable("Background transition caller"));
    }

    static void keepPresentationNonOpaque(JRootPane root)
    {
        // JFrame's constructor invokes setBackground before ViewerWindow fields initialize.
        if (root == null) return;
        root.setOpaque(false);
        root.getLayeredPane().setOpaque(false);
        if (root.getContentPane() instanceof javax.swing.JComponent)
            ((javax.swing.JComponent)root.getContentPane()).setOpaque(false);
    }

    boolean applyAlwaysOnTop(boolean requested)
    {
        assert SwingUtilities.isEventDispatchThread();
        return WindowStacking.apply(requested,this::isAlwaysOnTopSupported,this::setAlwaysOnTop);
    }

    int effectiveOpacity() { return BackgroundOpacity.effective(requestedOpacity,supported); }

    String transparencyDiagnostics()
    {
        Color background = getBackground();
        return "requested="+requestedOpacity+" effective="+effectiveOpacity()+" supported="+supported
            +" nativeAlpha="+(background==null?-1:background.getAlpha())
            +" configurationCapable="+getGraphicsConfiguration().isTranslucencyCapable()
            +" configurationPixelBits="+getGraphicsConfiguration().getColorModel().getPixelSize()
            +" undecorated="+isUndecorated()+" surfaceBackground="+surface.backgroundArgb()
            +" finalBufferBackground="+presentation.backgroundArgb()+" destination="+presentation.destinationFormat();
    }


    @Override public void paint(Graphics graphics)
    {
        // Buffer ABOVE Window.paint: it clears a non-opaque window before painting its children.
        // Buffering only Surface.paint leaves that clear visible on the native window.
        paintingWindow = true;
        try
        {
            presentation.paint(graphics,getWidth(),getHeight(),this::paintHierarchy);
            presented.run();
        }
        finally { paintingWindow = false; }
    }

    // Read-only diagnostic: distinguishes top-level composition from a direct Swing subtree paint.
    boolean isPaintingWindow() { return paintingWindow; }

    private void paintHierarchy(Graphics2D graphics)
    {
        super.paint(graphics);
    }

    private void installResize(Component component)
    {
        MouseAdapter listener = new MouseAdapter()
        {
            private Point pointer;
            private Rectangle bounds;
            private int edges;
            @Override public void mouseMoved(MouseEvent event)
            {
                int hit = (getExtendedState() & Frame.MAXIMIZED_BOTH) != 0 ? 0
                    : WindowGeometry.edges(event.getX(),event.getY(),component.getWidth(),component.getHeight());
                component.setCursor(Cursor.getPredefinedCursor(WindowGeometry.cursor(hit)));
            }
            @Override public void mouseExited(MouseEvent event)
            {
                if (pointer == null) component.setCursor(Cursor.getDefaultCursor());
            }
            @Override public void mousePressed(MouseEvent event)
            {
                if (!SwingUtilities.isLeftMouseButton(event) || (getExtendedState() & Frame.MAXIMIZED_BOTH) != 0) return;
                edges = WindowGeometry.edges(event.getX(),event.getY(),component.getWidth(),component.getHeight());
                if (edges == 0) return;
                pointer = event.getLocationOnScreen(); bounds = getBounds();
            }
            @Override public void mouseDragged(MouseEvent event)
            {
                if (pointer == null) return;
                Point now = event.getLocationOnScreen();
                setBounds(WindowGeometry.resize(bounds,edges,now.x-pointer.x,now.y-pointer.y,getMinimumSize()));
            }
            @Override public void mouseReleased(MouseEvent event)
            {
                pointer = null;
                component.setCursor(Cursor.getDefaultCursor());
            }
        };
        component.addMouseListener(listener); component.addMouseMotionListener(listener);
    }

    void revealControls() { surface.reveal = true; surface.repaint(); }

    void setPresentationListener(Runnable listener)
    {
        presented = listener;
        surface.presented = () -> { if (!paintingWindow) presented.run(); };
    }

    void setModelPainter(Consumer<Graphics2D> painter)
    {
        surface.modelPainter = painter;
    }

    // At zero opacity, hovering reveals the background so the window remains discoverable.
    void installHoverControls()
    {
        MouseAdapter hover = new MouseAdapter()
        {
            @Override public void mouseEntered(MouseEvent e) { surface.reveal = true; surface.repaint(); }
            @Override public void mouseExited(MouseEvent e)
            {
                SwingUtilities.invokeLater(() -> {
                    surface.reveal = surface.getMousePosition(true) != null;
                    surface.repaint();
                });
            }
        };
        installHover(surface, hover);
    }

    private static void installHover(java.awt.Component component, MouseAdapter hover)
    {
        component.addMouseListener(hover);
        if (component instanceof java.awt.Container)
            for (java.awt.Component child : ((java.awt.Container) component).getComponents()) installHover(child, hover);
    }

    static final class Surface extends JPanel
    {
        int opacity = 100;
        boolean reveal;
        Consumer<Graphics2D> modelPainter = g -> {};
        private BufferedImage ui, composed;
        Runnable presented = () -> {};
        Surface()
        {
            super(new BorderLayout(8,8));
            setOpaque(false);
            setDoubleBuffered(false);
        }
        // Child dirty regions must repaint through the compositing boundary.
        @Override protected boolean isPaintingOrigin() { return true; }

        @Override public void paint(Graphics graphics)
        {
            int width = getWidth(), height = getHeight();
            if (width <= 0 || height <= 0) return;
            if (ui == null || ui.getWidth() != width || ui.getHeight() != height)
            {
                ui = new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);
                composed = new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);
            }
            Graphics2D layer = ui.createGraphics();
            try
            {
                layer.setComposite(AlphaComposite.Clear);
                layer.fillRect(0,0,width,height);
                layer.setComposite(AlphaComposite.SrcOver);
                // No shared Swing back buffer may bypass this layer.
                disableBuffering(this);
                super.paint(layer);
            }
            finally { layer.dispose(); }
            Graphics2D result = composed.createGraphics();
            try
            {
                result.setComposite(AlphaComposite.Clear);
                result.fillRect(0,0,width,height);
                int effective = opacity == 0 && reveal ? 100 : opacity;
                result.setComposite(AlphaComposite.SrcOver.derive(effective / 100f));
                result.drawImage(ui,0,0,null);
                result.setComposite(AlphaComposite.SrcOver);
                modelPainter.accept(result);
            }
            finally { result.dispose(); }
            Graphics2D target = (Graphics2D) graphics.create();
            try
            {
                target.setComposite(AlphaComposite.Src);
                target.drawImage(composed,0,0,null);
            }
            finally { target.dispose(); }
            presented.run();
        }

        String backgroundArgb()
        {
            // Inside the six-pixel surface border, outside the model/HUD viewport.
            return composed == null ? "unpainted" : String.format("%08x",composed.getRGB(Math.max(0,composed.getWidth()-2),Math.max(0,composed.getHeight()-2)));
        }

        private static void disableBuffering(java.awt.Component component)
        {
            if (component instanceof javax.swing.JComponent) ((javax.swing.JComponent) component).setDoubleBuffered(false);
            if (component instanceof java.awt.Container)
                for (java.awt.Component child : ((java.awt.Container) component).getComponents()) disableBuffering(child);
        }

        @Override protected void paintComponent(Graphics graphics)
        {
            graphics.setColor(BackgroundOpacity.color(100));
            graphics.fillRect(0,0,getWidth(),getHeight());
        }
    }
}

package com.modelpopout;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Rectangle;

/** Geometry for invisible native-style resize edges. */
final class WindowGeometry
{
    static final int NORTH = 1, EAST = 2, SOUTH = 4, WEST = 8;
    static final int BORDER = 6;

    static int edges(int x, int y, int width, int height)
    {
        int edges = 0;
        if (x < BORDER) edges |= WEST;
        else if (x >= width-BORDER) edges |= EAST;
        if (y < BORDER) edges |= NORTH;
        else if (y >= height-BORDER) edges |= SOUTH;
        return edges;
    }

    static int cursor(int edges)
    {
        switch (edges)
        {
            case NORTH: return Cursor.N_RESIZE_CURSOR;
            case EAST: return Cursor.E_RESIZE_CURSOR;
            case SOUTH: return Cursor.S_RESIZE_CURSOR;
            case WEST: return Cursor.W_RESIZE_CURSOR;
            case NORTH | EAST: return Cursor.NE_RESIZE_CURSOR;
            case NORTH | WEST: return Cursor.NW_RESIZE_CURSOR;
            case SOUTH | EAST: return Cursor.SE_RESIZE_CURSOR;
            case SOUTH | WEST: return Cursor.SW_RESIZE_CURSOR;
            default: return Cursor.DEFAULT_CURSOR;
        }
    }

    static Rectangle resize(Rectangle start, int edges, int dx, int dy, Dimension minimum)
    {
        Rectangle next = new Rectangle(start);
        if ((edges & EAST) != 0) next.width = Math.max(minimum.width,start.width+dx);
        if ((edges & SOUTH) != 0) next.height = Math.max(minimum.height,start.height+dy);
        if ((edges & WEST) != 0)
        {
            next.width = Math.max(minimum.width,start.width-dx);
            next.x = start.x+start.width-next.width;
        }
        if ((edges & NORTH) != 0)
        {
            next.height = Math.max(minimum.height,start.height-dy);
            next.y = start.y+start.height-next.height;
        }
        return next;
    }
}

package com.modelpopout;

import java.awt.AlphaComposite;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;

/** EDT-owned buffer at the native Window.paint boundary, including AWT's background clear. */
final class WindowPresentation
{
    private BufferedImage buffer;
    private final boolean diagnostics = Boolean.getBoolean("modelpopout.paintDiagnostics");
    private String destinationFormat = "unpainted";

    // Read-only trace of the outer border pixel, away from model/HUD content.
    String backgroundArgb()
    {
        return buffer == null ? "unpainted" : String.format("%08x",buffer.getRGB(0,0));
    }

    String destinationFormat() { return destinationFormat; }

    void paint(Graphics graphics, int width, int height, Consumer<Graphics2D> hierarchy)
    {
        assert SwingUtilities.isEventDispatchThread();
        if (width <= 0 || height <= 0) return;
        if (diagnostics && graphics instanceof Graphics2D)
        {
            java.awt.image.ColorModel format = ((Graphics2D)graphics).getDeviceConfiguration().getColorModel();
            destinationFormat = "bits="+format.getPixelSize()+",alpha="+format.hasAlpha();
        }
        if (buffer == null || buffer.getWidth() != width || buffer.getHeight() != height)
            buffer = new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);

        Graphics2D frame = buffer.createGraphics();
        try
        {
            frame.setComposite(AlphaComposite.Clear);
            frame.fillRect(0,0,width,height);
            frame.setComposite(AlphaComposite.SrcOver);
            // Window.paint may clear again. Both that clear and all child paints stay private.
            hierarchy.accept(frame);
        }
        finally { frame.dispose(); }

        Graphics2D target = (Graphics2D) graphics.create();
        try
        {
            target.setComposite(AlphaComposite.Src);
            target.drawImage(buffer,0,0,null);
        }
        finally { target.dispose(); }
    }
}

package com.modelpopout;

import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/** Apply only to the viewer's Window; a rejected desktop request must not disrupt rendering. */
final class WindowStacking
{
    static boolean apply(boolean requested, BooleanSupplier supported, Consumer<Boolean> setAlwaysOnTop)
    {
        try
        {
            if (requested && !supported.getAsBoolean()) return false;
            setAlwaysOnTop.accept(requested);
            return true;
        }
        catch (UnsupportedOperationException | SecurityException unavailable)
        {
            return false;
        }
    }
}

package com.modelpopout;

import java.awt.Color;
import java.awt.IllegalComponentStateException;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Native background/configuration recovery only; never applies whole-window opacity. */
final class WindowTransparency
{
    private static final Color TRANSPARENT = new Color(0,0,0,0);

    static boolean apply(boolean available, BooleanSupplier capable, Supplier<Color> background,
        Consumer<Color> setBackground)
    {
        if (available)
        {
            try
            {
                Color current = background.get();
                // AWT negotiates an alpha-capable configuration only on opaque -> translucent.
                // Repeating an already-transparent color is a no-op after a configuration change.
                if (!capable.getAsBoolean() && current != null && current.getAlpha() < 255)
                    setBackground.accept(BackgroundOpacity.color(100));
                setBackground.accept(TRANSPARENT);
                Color applied = background.get();
                if (capable.getAsBoolean() && applied != null && applied.getAlpha() == 0) return true;
            }
            catch (UnsupportedOperationException | IllegalComponentStateException unavailable)
            {
                // A desktop/device can reject translucency despite its advertised capability.
            }
        }
        setBackground.accept(BackgroundOpacity.color(100));
        return false;
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;
import static org.junit.Assert.*;

public class AnimatedTextureTest
{
    @Test public void nativeClockDoesNotRunAwayWhenClientLosesFocusOrStopsAdvancing()
    {
        TextureClock clock = new TextureClock();
        clock.observe(100,1000000000L);
        assertEquals(100,clock.phase(1000000000L),0);
        assertEquals(100.5,clock.phase(1010000000L),0);
        assertEquals(101,clock.phase(2000000000L),0);
        assertFalse(clock.advancing(2000000000L));
        clock.observe(100,2000000000L); // Repeated events at the same cycle do not restart free-running motion.
        assertEquals(101,clock.phase(2000000000L),0);
        clock.observe(110,2000000000L);
        assertEquals(110,clock.phase(2000000000L),0);
        clock.clear();
        assertFalse(clock.advancing(3000000000L));
    }

    @Test public void allDirectionsSpeedWrapAndCpuAlreadyScrolledPixelsUseCorrectOffsets()
    {
        int[] pixels=new int[16];
        for(int i=0;i<pixels.length;i++) pixels[i]=0x100000+i+1;
        for(int direction=1;direction<=4;direction++)
        {
            TextureSet.Pixels texture=new TextureSet.Pixels(pixels,direction,1,0,0);
            TextureSet cpu=new TextureSet(Collections.singletonMap(0,texture),50,false);
            assertEquals(0xff000000|pixels[0],texture.sampleArgb(.125,.125,50,cpu));
            int index=direction==1?12:direction==3?4:direction==2?3:1;
            int moved=texture.sampleArgb(.125,.125,51,cpu);
            assertEquals(0xff000000|pixels[index],moved);
            assertEquals(0xff000000|pixels[0],texture.sampleArgb(.125,.125,54,cpu));
            TextureSet gpu=new TextureSet(cpu.textures,50,true);
            assertEquals(moved,texture.sampleArgb(.125,.125,32,gpu)); // One texel of a 4px fixture in GPU's 128-unit clock.
        }
        TextureSet.Pixels fast=new TextureSet.Pixels(pixels,4,2,0,0);
        TextureSet cpu=new TextureSet(Collections.singletonMap(0,fast),0,false);
        assertEquals(0xff000000|pixels[1],fast.sampleArgb(.125,.125,.5,cpu));
    }

    @Test public void fractionalAnimationFiltersRealTexelsAndRetainsCutoutAlpha()
    {
        TextureSet.Pixels texture=new TextureSet.Pixels(new int[]{0xff0000,0,0xff0000,0},4,1,0,0);
        TextureSet set=new TextureSet(Collections.singletonMap(0,texture),0,false);
        int halfway=texture.sampleArgb(.25,.25,.5,set);
        assertEquals(128,halfway>>>24);
        assertEquals(0xff0000,halfway&0xffffff);
        assertEquals(0,texture.sampleArgb(.25,.25,1,set));
    }

    @Test public void uniformTexturesDoNotScheduleDuplicateAnimationFrames()
    {
        TextureSet set = new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(new int[]{0xff0000},1,1,0,0)),0,true);
        assertFalse(set.animated());
    }

    @Test public void cachedAndUncachedRasterizationAgreeIncludingCutoutsAndCoincidentFaces()
    {
        TextureRenderingTest.TexturedModel nativeModel = new TextureRenderingTest.TexturedModel()
        {
            @Override public int getFaceCount() { return 2; }
            @Override public int[] getFaceIndices1() { return new int[]{0,0}; }
            @Override public int[] getFaceIndices2() { return new int[]{2,2}; }
            @Override public int[] getFaceIndices3() { return new int[]{1,1}; }
            @Override public int[] getFaceColors1() { return new int[]{127,20000}; }
            @Override public int[] getFaceColors2() { return getFaceColors1(); }
            @Override public int[] getFaceColors3() { return getFaceColors1(); }
            @Override public short[] getFaceTextures() { return new short[]{0,-1}; }
            @Override public byte[] getFaceTransparencies() { return new byte[]{0,0}; }
            @Override public byte[] getTextureFaces() { return new byte[]{-1,-1}; }
        };
        ModelSnapshot mesh = ModelSnapshot.capture(nativeModel,null).toRgb();
        CameraView camera = new CameraView(0,0,1);ModelFrame frame = ModelFrame.initial(mesh);
        ModelProjection projection = mesh.projection(camera,frame);
        TextureRasterPlan plan = projection.rasterPlan(mesh);
        assertNotNull(plan);
        ModelRenderer renderer = new ModelRenderer();
        for (int[] pixels : new int[][]{{0xff0000,0x00ff00,0x0000ff,0xffffff},{0xff0000,0,0,0xffffff}})
        {
            TextureSet set = new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(pixels,2,1,0,0)),0,false);
            for (double phase : new double[]{0,.25,.5,1})
            {
                BufferedImage cached = plan.render(set,phase);
                BufferedImage plain = renderer.rasterize(mesh,projection,set,phase);
                assertArrayEquals(plain.getRGB(0,0,512,512,null,0,512),cached.getRGB(0,0,512,512,null,0,512));
            }
        }
    }

    @Test public void animatedTextureFramesReuseTheCapturedPoseProjectionAndRasterPlan()
    {
        ModelSnapshot mesh=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel(),null);
        CameraView camera=new CameraView(0,0,1);ModelFrame frame=ModelFrame.initial(mesh);
        int[] pixels={0xff0000,0x00ff00,0x0000ff,0xffffff};
        TextureSet set=new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(pixels,2,1,0,0)),0,false);
        ModelRenderer renderer=new ModelRenderer();
        BufferedImage first=renderer.render(mesh,camera,frame,set,0);
        ModelProjection projection=mesh.toRgb().projection(camera,frame);
        TextureRasterPlan plan=projection.rasterPlan(mesh.toRgb());
        assertNotNull(plan);
        assertTrue(plan.fragments() > 0 && plan.fragments() <= TextureRasterPlan.MAX_FRAGMENTS);
        int[] old=first.getRGB(0,0,512,512,null,0,512);
        BufferedImage later=renderer.render(mesh,camera,frame,set,.5);
        assertFalse(Arrays.equals(old,later.getRGB(0,0,512,512,null,0,512)));
        assertSame(projection,mesh.toRgb().projection(camera,frame));
        assertSame(plan,projection.rasterPlan(mesh.toRgb()));
        assertArrayEquals(old,first.getRGB(0,0,512,512,null,0,512));
        assertSame(later,renderer.render(mesh,camera,frame,set,.5));
    }

    @Test public void texturesAdvanceEvenWithoutNewGeometryAndLifecycleClearInvalidatesOldFrames()
    {
        ModelSnapshot mesh=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel(),null);
        TextureSet textures=new TextureSet(Collections.singletonMap(0,new TextureSet.Pixels(new int[]{0xff0000,0x00ff00,0x0000ff,0xffffff},1,1,0,0)),0,true);
        LiveViewState state=new LiveViewState();state.updateModel(mesh,false);state.updateTextures(textures);
        state.setTexturePhase(50);LiveViewState.RenderRequest first=state.begin();state.finish(first);
        assertFalse(state.updateModel(mesh,false));state.setTexturePhase(50.5);
        LiveViewState.RenderRequest next=state.begin();
        assertSame(first.model,next.model);assertSame(first.framing,next.framing);
        assertEquals(50.5,next.texturePhase,0);
        state.clear();assertFalse(state.finish(next));assertFalse(state.hasAnimatedTextures());assertNull(state.begin());
    }
}

package com.modelpopout;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class BackgroundOpacityTest
{
    @Test public void opacityLimitsAndUnsupportedFallbackAreSafe()
    {
        assertEquals(0,BackgroundOpacity.clamp(-100));
        assertEquals(100,BackgroundOpacity.clamp(200));
        assertEquals(0,BackgroundOpacity.alpha(0));
        assertEquals(128,BackgroundOpacity.alpha(50));
        assertEquals(255,BackgroundOpacity.alpha(100));
        assertEquals(100,BackgroundOpacity.effective(0,false));
        assertEquals(0,BackgroundOpacity.effective(0,true));
    }

    @Test public void backgroundAlphaNeverFadesModelsOrErasesBlackDetails()
    {
        BufferedImage models = new BufferedImage(3,1,BufferedImage.TYPE_INT_ARGB);
        models.setRGB(0,0,0xffff0000);
        models.setRGB(1,0,0xff000000);
        for(int percent : new int[]{0,25,50,100})
        {
            BufferedImage composed = BackgroundOpacity.compose(models,percent);
            assertEquals(0xffff0000,composed.getRGB(0,0));
            assertEquals(0xff000000,composed.getRGB(1,0));
            assertEquals(BackgroundOpacity.alpha(percent),composed.getRGB(2,0) >>> 24);
        }
    }

    @Test public void decreasingOpacityClearsOldPixelsInsteadOfAccumulatingOpaqueBackground() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            surface.setSize(10,10);
            BufferedImage image = new BufferedImage(10,10,BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = image.createGraphics();
            try
            {
                surface.opacity = 100; surface.paint(g);
                assertEquals(255,image.getRGB(5,5) >>> 24);
                surface.opacity = 50; surface.paint(g);
                assertEquals(128,image.getRGB(5,5) >>> 24);
                surface.opacity = 0; surface.paint(g);
                assertEquals(0,image.getRGB(5,5) >>> 24);
            }
            finally { g.dispose(); }
        });
    }

    @Test public void repeatedFrozenFramePaintingKeepsModelOpaqueInBothBackgroundModes() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            BufferedImage frozen = new BufferedImage(10,10,BufferedImage.TYPE_INT_ARGB);
            frozen.setRGB(5,5,0xffff0000);
            ViewerWindow.Surface surface = new ViewerWindow.Surface();
            surface.setSize(10,10);
            surface.modelPainter = g -> g.drawImage(frozen,0,0,null);
            for (int opacity : new int[]{100,50,0})
            {
                surface.opacity = opacity;
                BufferedImage target = new BufferedImage(10,10,BufferedImage.TYPE_INT_ARGB);
                Graphics2D g = target.createGraphics();
                try
                {
                    for (int i = 0; i < 100; i++)
                    {
                        surface.paint(g);
                        assertEquals(0xffff0000,target.getRGB(5,5));
                        assertEquals(BackgroundOpacity.alpha(opacity),target.getRGB(1,1) >>> 24);
                    }
                }
                finally { g.dispose(); }
            }
        });
    }

    @Test public void settingsSliderUsesSavedKeyAndSurvivesPanelRecreationWithoutFeedbackWrites() throws Exception
    {
        Map<String,Object> saved = new HashMap<>();
        ModelPopoutConfig config = new ModelPopoutConfig()
        {
            @Override public int backgroundOpacity() { return (int) saved.getOrDefault(OPACITY_KEY,100); }
            @Override public boolean renderNpc() { return (boolean) saved.getOrDefault(NPC_KEY,true); }
        };
        SwingUtilities.invokeAndWait(() -> {
            int[] writes = {0};
            ViewerSettingsPanel first = new ViewerSettingsPanel(config,(key,value) -> { saved.put(key,value); writes[0]++; },() -> {});
            assertEquals(0,writes[0]);
            first.opacity.setValue(37);
            assertEquals(37,saved.get(ModelPopoutConfig.OPACITY_KEY));
            ViewerSettingsPanel reopened = new ViewerSettingsPanel(config,(key,value) -> { saved.put(key,value); writes[0]++; },() -> {});
            assertEquals(37,reopened.opacity.getValue());
            saved.put(ModelPopoutConfig.OPACITY_KEY,0);
            reopened.sync(config);
            assertEquals(0,reopened.opacity.getValue());
            assertEquals(1,writes[0]);
            reopened.npcs.doClick();
            assertEquals(false,saved.get(ModelPopoutConfig.NPC_KEY));
        });
