package com.modelpopout;

import java.awt.Container;
import java.awt.Rectangle;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.JComponent;
import javax.swing.JRootPane;
import javax.swing.RepaintManager;
import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

/** Exercises the real ModelPanel repaint entry point, not a manually selected surface painter. */
public class HudRepaintRoutingTest
{
    @Test public void hudDirtyRequestsUseTheWholeCompositorRatherThanTheChildRectangle() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            RepaintManager previous=RepaintManager.currentManager((JComponent)null);
            Requests requests=new Requests();RepaintManager.setCurrentManager(requests);
            Fixture f=new Fixture();
            try
            {
                for(int[] size:new int[][]{{480,300},{1024,512},{640,480}})
                    for(int opacity:new int[]{0,30,50,100})
                    {
                        f.resize(size[0],size[1]);f.surface.opacity=opacity;requests.dirty.clear();
                        f.model.repaint();
                        assertEquals("HUD must invalidate the same component as completed model frames",1,requests.dirty.size());
                        assertTrue("Child-only dirty regions reintroduce a separate native presentation path",requests.dirty.containsKey(f.surface));
                        Rectangle region=requests.dirty.get(f.surface);
                        assertEquals(new Rectangle(0,0,size[0],size[1]),region);
                        f.nativeParent.last=null;f.surface.paintImmediately(region);
                        assertEquals("Native update must include the entire composed surface",region,f.nativeParent.last);
                    }
            }
            finally {f.root.removeNotify();RepaintManager.setCurrentManager(previous);}
        });
    }

    @Test public void interleavedHudAndCompletedModelRequestsShareOneDirtySource() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            RepaintManager previous=RepaintManager.currentManager((JComponent)null);
            Requests requests=new Requests();RepaintManager.setCurrentManager(requests);
            Fixture f=new Fixture();
            try
            {
                f.resize(1024,512);requests.dirty.clear();
                for(int i=0;i<1000;i++)
                {
                    f.model.repaint(5,7,13,17); // HUD/config/expiration invalidation.
                    f.surface.repaint();       // Existing completed-model publication path.
                }
                assertEquals("One component can coalesce both update sources",1,requests.dirty.size());
                assertEquals(new Rectangle(0,0,1024,512),requests.dirty.get(f.surface));
                assertFalse(requests.dirty.containsKey(f.model));
            }
            finally {f.root.removeNotify();RepaintManager.setCurrentManager(previous);}
        });
    }

    @Test public void reopenedViewUsesItsOwnSurfaceAndDetachedPanelsKeepNormalSwingBehavior() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            RepaintManager previous=RepaintManager.currentManager((JComponent)null);
            Requests requests=new Requests();RepaintManager.setCurrentManager(requests);
            Fixture oldView=new Fixture(),reopened=new Fixture();
            try
            {
                requests.dirty.clear();oldView.model.repaint();
                assertTrue(requests.dirty.containsKey(oldView.surface));assertFalse(requests.dirty.containsKey(reopened.surface));
                requests.dirty.clear();reopened.model.repaint();
                assertTrue(requests.dirty.containsKey(reopened.surface));assertFalse(requests.dirty.containsKey(oldView.surface));
                oldView.surface.remove(oldView.model);requests.dirty.clear();oldView.model.repaint();
                assertTrue(requests.dirty.containsKey(oldView.model));assertFalse(requests.dirty.containsKey(oldView.surface));
                javax.swing.JPanel otherParent=new javax.swing.JPanel();otherParent.add(oldView.model);
                requests.dirty.clear();oldView.model.repaint();
                assertTrue(requests.dirty.containsKey(oldView.model));assertFalse(requests.dirty.containsKey(otherParent));
            }
            finally {oldView.root.removeNotify();reopened.root.removeNotify();RepaintManager.setCurrentManager(previous);}
        });
    }

    @Test public void opaqueNativeFallbackMustNotStopSwingAtTheSurface() throws Exception
    {
        SwingUtilities.invokeAndWait(() -> {
            Fixture f=new Fixture();
            try
            {
                f.resize(1024,512);
                // Reproduce Window.setBackground's alpha-to-255 setLayersOpaque side effect.
                f.root.setOpaque(true);f.root.getLayeredPane().setOpaque(true);f.surface.setOpaque(true);
                f.nativeParent.last=null;f.surface.paintImmediately(0,0,1024,512);
                assertNull("Opaque Swing ancestor bypasses the native Window.paint path",f.nativeParent.last);
                ViewerWindow.keepPresentationNonOpaque(f.root);
                assertFalse(f.root.isOpaque());assertFalse(f.root.getLayeredPane().isOpaque());assertFalse(f.surface.isOpaque());
                f.surface.paintImmediately(0,0,1024,512);
                assertEquals(new Rectangle(0,0,1024,512),f.nativeParent.last);
                // Model and HUD invalidations, root updates and resized fallback remain routed.
                for(int width:new int[]{480,1024,640})
                {
                    f.resize(width,300);
                    for(JComponent component:new JComponent[]{f.model,f.surface,f.root,f.root.getLayeredPane()})
                    {
                        f.nativeParent.last=null;component.paintImmediately(0,0,component.getWidth(),component.getHeight());
                        assertNotNull("Every Swing origin must ascend to the native presentation",f.nativeParent.last);
                    }
                }
            }
            finally {f.root.removeNotify();}
        });
    }

    private static final class Fixture
    {
        final NativeParent nativeParent=new NativeParent();
        final JRootPane root=new JRootPane();
        final ViewerWindow.Surface surface=new ViewerWindow.Surface();
        final ModelPopoutPlugin.ModelPanel model=new ModelPopoutPlugin().new ModelPanel(new ModelPopoutConfig() {});
        Fixture()
        {
            root.setOpaque(false);root.getLayeredPane().setOpaque(false);
            root.setContentPane(surface);surface.setBorder(javax.swing.BorderFactory.createEmptyBorder(6,6,6,6));
            surface.add(model);nativeParent.add(root);resize(480,300);root.addNotify();
        }
        void resize(int width,int height)
        {
            nativeParent.setSize(width,height);root.setSize(width,height);root.doLayout();
            surface.setSize(width,height);surface.doLayout();
        }
    }
    private static final class NativeParent extends Container
    {
        Rectangle last;
        @Override public boolean isShowing(){return true;}
        @Override public void repaint(long delay,int x,int y,int width,int height){last=new Rectangle(x,y,width,height);}
    }
    private static final class Requests extends RepaintManager
    {
        // Capture Swing's submitted target/rectangle before the native-window visibility filter.
        // A real Window cannot be constructed headlessly. paintImmediately above uses JDK routing.
        final Map<JComponent,Rectangle> dirty=new LinkedHashMap<>();
        @Override public void addDirtyRegion(JComponent component,int x,int y,int width,int height)
        {
            if(width<=0 || height<=0)return;
            Rectangle next=new Rectangle(x,y,width,height);
            dirty.merge(component,next,(old,value) -> old.union(value));
        }
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.HashSet;
import org.junit.Test;
import static org.junit.Assert.*;

public class HudTrackerTest
{
    private final Object player=new Object(),npc=new Object();
    private final HudTracker tracker=new HudTracker();
    private final BufferedImage image=new BufferedImage(3,3,BufferedImage.TYPE_INT_ARGB);
    private final HitsplatStyle nativeStyle=HitsplatStyle.decode(new byte[]{9,0,50,0});
    private HudSnapshot sample(int cycle)
    { return tracker.sample(1,cycle,HudHealth.UNKNOWN,HudHealth.UNKNOWN,HudAssets.HealthSkin.FALLBACK); }
    private boolean hit(Object actor,int amount,int expiry,int cycle,HitsplatStyle style)
    { return tracker.add(actor,16,amount,expiry,cycle,style,image); }

    @Test public void multipleHitsKeepValuesSeparateAndExpireOnNativeCycles()
    {
        tracker.selectPlayer(player);tracker.selectNpc(npc,7);
        assertTrue(hit(player,0,150,100,nativeStyle));
        assertTrue(tracker.add(player,65,8,151,100,nativeStyle,image));
        assertTrue(tracker.add(player,6,12,152,100,nativeStyle,image));
        assertTrue(hit(player,30,153,100,nativeStyle));
        assertTrue(hit(npc,90,150,100,nativeStyle));
        assertFalse(hit(new Object(),99,150,100,nativeStyle));
        assertFalse(hit(null,99,150,100,nativeStyle));
        assertFalse(hit(player,99,154,100,nativeStyle)); // Native default rejects a fifth visible hit.
        HudSnapshot first=sample(100);
        assertEquals(4,first.player.hits.size());assertEquals(1,first.npc.hits.size());
        HashSet<Integer> slots=new HashSet<>();for(HudSnapshot.Hit h:first.player.hits) slots.add(h.slot);
        assertEquals(4,slots.size());assertEquals(0,first.player.hits.get(0).amount);
        assertEquals(65,first.player.hits.get(1).type);assertEquals(6,first.player.hits.get(2).type);
        assertEquals(4,sample(149).player.hits.size());assertEquals(3,sample(150).player.hits.size());
        assertTrue(sample(153).player.hits.isEmpty());assertTrue(sample(153).npc.hits.isEmpty());
        assertEquals(4,first.player.hits.size()); // Already published data remains unchanged.
        try { first.player.hits.clear();fail(); } catch(UnsupportedOperationException expected) { }
    }

    @Test public void targetSwitchDespawnLogoutAndReopeningCannotTransferHits()
    {
        long firstKey=tracker.selectPlayer(player);tracker.selectNpc(npc,7);
        hit(player,5,150,100,nativeStyle);hit(npc,8,150,100,nativeStyle);
        tracker.selectNpc(new Object(),8);assertTrue(sample(101).npc.hits.isEmpty());
        assertEquals(1,sample(101).player.hits.size());
        tracker.selectNpc(npc,9);hit(npc,8,150,101,nativeStyle);
        tracker.selectNpc(null,-1);assertEquals(-1,sample(102).npcKey);assertTrue(sample(102).npc.hits.isEmpty());
        assertFalse(hit(npc,9,150,102,nativeStyle));
        tracker.clear();assertTrue(sample(103).player.hits.isEmpty());
        assertTrue(tracker.selectPlayer(player)>firstKey);assertTrue(sample(104).player.hits.isEmpty());
        tracker.selectNpc(npc,10);hit(npc,8,150,105,nativeStyle);
        tracker.selectNpc(npc,11);assertTrue(sample(106).npc.hits.isEmpty()); // Reused identity, new lifecycle key.
    }

    @Test public void replacementPrioritiesMatchFourSlotBehavior()
    {
        tracker.selectPlayer(player);
        for(int i=0;i<4;i++) hit(player,10+i,150+i,100,nativeStyle);
        HitsplatStyle smallest=HitsplatStyle.decode(new byte[]{12,1,0});
        assertFalse(hit(player,10,170,100,smallest));assertTrue(hit(player,20,170,100,smallest));
        assertEquals(20,sample(100).player.hits.get(0).amount);
        HitsplatStyle earliest=HitsplatStyle.decode(new byte[]{12,0,0});
        assertTrue(hit(player,1,180,100,earliest));assertEquals(1,sample(100).player.hits.get(1).amount);
        assertFalse(hit(player,99,180,100,HitsplatStyle.decode(new byte[]{12,2,0})));
    }

    @Test public void idlePacketsAreReusedAndDelayedHitsRespectStartAndCycleWrap()
    {
        tracker.selectPlayer(player);HudSnapshot idle=sample(10);assertSame(idle,sample(11));
        assertTrue(hit(player,1,200,100,nativeStyle));HudSnapshot delayed=sample(100);
        assertFalse(delayed.player.hits.get(0).visible(149));assertTrue(delayed.player.hits.get(0).visible(150));
        assertNotSame(delayed,sample(101));assertSame(sample(101),sample(101));
        tracker.clear();tracker.selectPlayer(player);
        int start=Integer.MAX_VALUE-10,expiry=start+50;
        assertTrue(hit(player,1,expiry,start,nativeStyle));assertEquals(1,sample(start+49).player.hits.size());
        assertTrue(sample(expiry).player.hits.isEmpty());
    }

    @Test public void deathHealingUnknownHealthAndHiddenBarsAreIndependentOfHits()
    {
        tracker.selectPlayer(player);tracker.selectNpc(npc,7);hit(npc,8,150,100,nativeStyle);
        HudSnapshot dead=tracker.sample(1,100,HudHealth.player(0,30,0,99),HudHealth.scaled(0,30),HudAssets.HealthSkin.FALLBACK);
        assertEquals(0,dead.npc.health.fraction,0);assertEquals(1,dead.npc.hits.size());
        HudSnapshot healed=tracker.sample(1,101,HudHealth.player(15,30,80,99),HudHealth.scaled(15,30),HudAssets.HealthSkin.FALLBACK);
        assertEquals(.5,healed.npc.health.fraction,0);assertEquals(80.0/99,healed.player.health.fraction,0);
        HudSnapshot hidden=sample(102);assertFalse(hidden.npc.health.visible);assertEquals(1,hidden.npc.hits.size());
    }
    @Test public void teardownRejectsInFlightHudWorkBeforeIdentityOrPublicationCanBeRevived()
    {
        long obsolete=tracker.generation();tracker.selectPlayer(player);tracker.clear();
        assertFalse(tracker.inGeneration(obsolete,() -> fail("old event must not revive actor references or hits")));
        assertTrue(tracker.inGeneration(tracker.generation(),() -> {
            tracker.selectPlayer(player);assertTrue(hit(player,8,150,100,nativeStyle));
        }));
        assertEquals(1,sample(100).player.hits.size());tracker.clear();assertTrue(sample(101).player.hits.isEmpty());
    }
    @Test public void inFlightModelCaptureCannotRebindHudIdentityAfterCloseOrLogout()
    {
        long obsolete=tracker.generation();tracker.clear();
        assertEquals(-1,tracker.selectPlayer(obsolete,player,() -> true));
        assertEquals(-1,tracker.selectPlayer(tracker.generation(),player,() -> false));
        assertFalse(hit(player,8,150,100,nativeStyle));
        long restored=tracker.selectPlayer(tracker.generation(),player,() -> true);
        assertTrue(restored>=0);assertTrue(hit(player,8,150,100,nativeStyle));
        assertEquals(restored,sample(100).player.key);
    }
}

package com.modelpopout;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

public class LatestHudMailboxTest
{
    static HudSnapshot packet(int cycle)
    { return new HudSnapshot(1,cycle,-1,new HudSnapshot.ActorHud(1,HudHealth.UNKNOWN,List.of()),
        new HudSnapshot.ActorHud(-1,HudHealth.UNKNOWN,List.of()),HudAssets.HealthSkin.FALLBACK); }
    @Test public void aThousandUpdatesQueueOneDeliveryOfLatestCompletedPacket()
    {
        ArrayDeque<Runnable> queue=new ArrayDeque<>();List<HudSnapshot> received=new ArrayList<>();
        LatestHudMailbox box=new LatestHudMailbox(queue::add,received::add);
        for(int i=0;i<1000;i++) box.offer(packet(i));
        assertEquals(1,queue.size());queue.remove().run();assertEquals(1,received.size());
        assertEquals(999,received.get(0).cycle);assertTrue(queue.isEmpty());
    }
    @Test public void racingOfferDuringDeliverySchedulesOneFollowUpWithoutLosingLatest()
    {
        ArrayDeque<Runnable> queue=new ArrayDeque<>();List<HudSnapshot> received=new ArrayList<>();
        LatestHudMailbox[] box=new LatestHudMailbox[1];
        box[0]=new LatestHudMailbox(queue::add,next -> {
            received.add(next);if(next.cycle==1) {box[0].offer(packet(2));box[0].offer(packet(3));assertTrue(queue.isEmpty());}
        });
        box[0].offer(packet(1));queue.remove().run();assertEquals(1,queue.size());queue.remove().run();
        assertEquals(2,received.size());assertEquals(3,received.get(1).cycle);assertTrue(queue.isEmpty());
    }
    @Test public void closeDropsPendingDataAndReopeningUsesSameBoundedDelivery()
    {
        ArrayDeque<Runnable> queue=new ArrayDeque<>();List<HudSnapshot> received=new ArrayList<>();
        LatestHudMailbox box=new LatestHudMailbox(queue::add,received::add);
        box.offer(packet(1));box.clear();queue.remove().run();assertTrue(received.isEmpty());
        box.offer(packet(2));box.clear();box.offer(packet(3));assertEquals(1,queue.size());
        queue.remove().run();assertEquals(3,received.get(0).cycle);
    }
}

package com.modelpopout;

import org.junit.Test;
import static org.junit.Assert.*;

public class LiveCaptureGateTest
{
    private LiveCaptureGate ready()
    {
        LiveCaptureGate gate = new LiveCaptureGate();
        gate.open();
        gate.setLoggedIn(true);
        return gate;
    }

    @Test public void averagesTwentySamplesPerSecondOnTwentyMillisecondTicks()
    {
        LiveCaptureGate gate = ready();
        int samples = 0;
        for (long ms = 0; ms < 1000; ms += 20)
        {
            long ticket = gate.acquire(ms * 1_000_000, false);
            if (ticket >= 0) { samples++; assertTrue(gate.complete(ticket)); }
        }
        assertEquals(20, samples);
    }

    @Test public void slowTicksSampleFreshStateWithoutCatchUpBursts()
    {
        LiveCaptureGate gate = ready();
        int samples = 0;
        for (long ms = 0; ms < 1000; ms += 200)
        {
            long ticket = gate.acquire(ms * 1_000_000, false);
            assertTrue(ticket >= 0);
            samples++;
            assertTrue(gate.complete(ticket));
            assertEquals(-1, gate.acquire(ms * 1_000_000, false));
        }
        assertEquals(5, samples);
    }

    @Test public void slowEdtAllowsOnlyOnePendingHandoff()
    {
        LiveCaptureGate gate = ready();
        long ticket = gate.acquire(0, false);
        for (long ms = 20; ms < 10000; ms += 20)
        {
            assertEquals(-1, gate.acquire(ms * 1_000_000, false));
            assertEquals(-1, gate.acquire(ms * 1_000_000, true));
        }
        assertTrue(gate.complete(ticket));
        assertTrue(gate.acquire(10_000_000_000L, false) >= 0);
    }

    @Test public void closeAndLogoutRejectOldCallbacksAndStopCapturing()
    {
        LiveCaptureGate gate = ready();
        long old = gate.acquire(0, false);
        gate.close();
        assertFalse(gate.complete(old));
        assertFalse(gate.current(old));
        assertEquals(-1, gate.acquire(100_000_000, true));
        gate.open();
        long fresh = gate.acquire(100_000_000, false);
        assertFalse(gate.complete(old));
        assertEquals(-1, gate.acquire(200_000_000, false));
        assertTrue(gate.complete(fresh));
        gate.setLoggedIn(false);
        assertEquals(-1, gate.acquire(300_000_000, true));
        assertFalse(gate.complete(fresh));
        gate.setLoggedIn(true);
        assertTrue(gate.acquire(300_000_000, false) >= 0);
    }

    @Test public void manualCaptureBypassesTimingButNotBackpressure()
    {
        LiveCaptureGate gate = ready();
        long ticket = gate.acquire(0, false);
        gate.complete(ticket);
        assertEquals(-1, gate.acquire(1, false));
        long manual = gate.acquire(1, true);
        assertTrue(manual >= 0);
        assertEquals(-1, gate.acquire(2, true));
        gate.complete(manual);
        assertEquals(-1, gate.acquire(3, false));
    }

    @Test public void configurationChangesRateImmediatelyAndClampsIt()
    {
        LiveCaptureGate gate = ready();
        gate.setRate(0);
        gate.complete(gate.acquire(0, false));
        assertEquals(-1, gate.acquire(999_999_999, false));
        gate.complete(gate.acquire(1_000_000_000, false));
        gate.setRate(1000);
        gate.complete(gate.acquire(1_000_000_001, false));
        assertEquals(-1, gate.acquire(1_020_000_000, false));
        assertTrue(gate.acquire(1_020_000_001, false) >= 0);
    }

    @Test public void negativeMonotonicClockValuesWork()
    {
        LiveCaptureGate gate = ready();
        gate.complete(gate.acquire(-1_000_000_000, false));
        assertEquals(-1, gate.acquire(-960_000_000, false));
        assertTrue(gate.acquire(-940_000_000, false) >= 0);
    }
}

package com.modelpopout;

import org.junit.Test;
import static org.junit.Assert.*;

public class LiveViewStateTest
{
    private ModelSnapshot pose(float y, int color, byte alpha)
    {
        return new ModelSnapshot(new float[]{0, 10, -10}, new float[]{y, 10, 10}, new float[]{0, 0, 0},
            new int[]{0}, new int[]{1}, new int[]{2}, new int[]{color}, new int[]{color}, new int[]{color}, new byte[]{alpha});
    }

    @Test public void identicalAppearanceSkipsRenderingButManualCaptureForcesIt()
    {
        LiveViewState state = new LiveViewState();
        assertTrue(state.updateModel(pose(0, 0xff0000, (byte) 0), false));
        LiveViewState.RenderRequest frame = state.begin();
        assertNotNull(frame);
        state.finish(frame);
        assertFalse(state.updateModel(pose(0, 0xff0000, (byte) 0), false));
        assertNull(state.begin());
        assertTrue(state.updateModel(pose(0, 0xff0000, (byte) 0), true));
        assertNotNull(state.begin());
    }

    @Test public void animationColorAndTransparencyChangesAreDetected()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        assertTrue(state.updateModel(pose(1, 0xff0000, (byte) 0), false));
        assertTrue(state.updateModel(pose(1, 0x00ff00, (byte) 0), false));
        assertTrue(state.updateModel(pose(1, 0x00ff00, (byte) 100), false));
    }

    @Test public void fallingBehindKeepsOnlyLatestPoseAndCamera()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        LiveViewState.RenderRequest first = state.begin();
        CameraView camera = new CameraView(1.5, .5, 2);
        ModelSnapshot last = null;
        for (int i = 1; i <= 1000; i++)
        {
            last = pose(i, 0xff0000, (byte) 0);
            state.updateModel(last, false);
            state.setCamera(camera);
            assertNull(state.begin());
        }
        assertTrue(state.finish(first));
        LiveViewState.RenderRequest latest = state.begin();
        assertSame(last, latest.model);
        assertSame(camera, latest.camera);
        state.finish(latest);
        assertNull(state.begin());
    }

    @Test public void modelUpdatesAndLogoutPreserveCamera()
    {
        LiveViewState state = new LiveViewState();
        CameraView camera = new CameraView(2, -.5, 1.8);
        state.setCamera(camera);
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        state.clear();
        assertNull(state.begin());
        state.updateModel(pose(1, 0x00ff00, (byte) 0), false);
        assertSame(camera, state.begin().camera);
    }

    @Test public void staleCompletionCannotReleaseNewSessionRender()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(0, 0xff0000, (byte) 0), false);
        LiveViewState.RenderRequest old = state.begin();
        state.clear();
        state.updateModel(pose(1, 0x00ff00, (byte) 0), false);
        assertNull(state.begin()); // Closing/reopening cannot add a second real rendering task.
        assertFalse(state.finish(old)); // Releases the slot, but rejects the invalidated image.
        LiveViewState.RenderRequest fresh = state.begin();
        assertNotNull(fresh);
        assertFalse(state.finish(old)); // Duplicate/stale completions cannot release the new task.
        assertNull(state.begin());
        assertTrue(state.finish(fresh));
    }

    @Test public void completedButNotYetPresentedSceneIsInvalidAfterNpcLayoutOrLogoutChanges()
    {
        LiveViewState state = new LiveViewState();state.setNpcEnabled(true);
        state.updateModel(pose(0,0xff0000,(byte)0),false);
        LiveViewState.RenderRequest completed = state.begin();assertTrue(state.finish(completed));
        assertTrue(state.valid(completed));
        state.setNpcEnabled(false);assertFalse(state.valid(completed));
        LiveViewState.RenderRequest replacement = state.begin();assertTrue(state.finish(replacement));
        assertTrue(state.valid(replacement));state.clear();assertFalse(state.valid(replacement));
    }

    @Test public void equivalentCameraDoesNotCreateDuplicateRenderWork()
    {
        LiveViewState state = new LiveViewState();state.updateModel(pose(0,0xff0000,(byte)0),false);
        state.finish(state.begin());
        state.setCamera(new CameraView(CameraView.DEFAULT.yaw,CameraView.DEFAULT.pitch,CameraView.DEFAULT.zoom));
        assertFalse(state.needsRender());
    }

    @Test public void snapshotConstructorOwnsInputArrays()
    {
        float[] x = {0, 10, -10}, y = {0, 10, 10}, z = {0, 0, 0};
        int[] a = {0}, b = {1}, c = {2}, colors = {0xff0000};
        byte[] alpha = {0};
        ModelSnapshot snapshot = new ModelSnapshot(x, y, z, a, b, c, colors, colors, colors, alpha);
        ModelSnapshot original = pose(0, 0xff0000, (byte) 0);
        x[0] = y[0] = z[0] = 99; a[0] = b[0] = c[0] = 99; colors[0] = 0; alpha[0] = 100;
        assertTrue(snapshot.sameAppearance(original));
    }
}

