package com.modelpopout;

import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

/** Synthetic triangles test rasterization only; the plugin never displays test fixtures. */
public class ModelRendererTest
{
    private static final CameraView TEST_VIEW = new CameraView(Math.toRadians(165), Math.toRadians(10), 1);

    private ModelSnapshot triangles(int nearColor, int farColor, byte nearAlpha, boolean reverse)
    {
        float[] x = new float[6], y = new float[6], z = new float[6];
        double yaw = Math.toRadians(165), pitch = Math.toRadians(10);
        for (int i = 0; i < 6; i++)
        {
            double sx = i % 3 == 0 ? -100 : i % 3 == 1 ? 100 : 0;
            double sy = i % 3 == 2 ? 100 : -100;
            double sz = i < 3 ? -10 : 10;
            // Inverse of the viewing rotation: overlapping triangles at distinct depths.
            double yy = sy * Math.cos(pitch) + sz * Math.sin(pitch);
            double rz = -sy * Math.sin(pitch) + sz * Math.cos(pitch);
            x[i] = (float) (sx * Math.cos(yaw) - rz * Math.sin(yaw));
            y[i] = (float) yy;
            z[i] = (float) (sx * Math.sin(yaw) + rz * Math.cos(yaw));
        }
        int[] a = {0, 3}, b = reverse ? new int[]{1, 4} : new int[]{2, 5};
        int[] c = reverse ? new int[]{2, 5} : new int[]{1, 4};
        int[] colors = {nearColor, farColor};
        return new ModelSnapshot(x, y, z, a, b, c, colors, colors, colors, new byte[]{nearAlpha, 0});
    }

    @Test public void nearerSurfaceWinsEvenWhenFarFaceIsLast()
    {
        BufferedImage image = new ModelRenderer().renderStatic(triangles(0x00ff00, 0xff0000, (byte) 0, false), TEST_VIEW);
        assertEquals(0x00ff00, image.getRGB(256, 256) & 0xffffff);
        assertEquals(ModelRenderer.BACKGROUND, image.getRGB(0, 0) & 0xffffff);
    }

    @Test public void backFacesAreCulledLikeTheNativeSoftwareRenderer()
    {
        BufferedImage image = new ModelRenderer().renderStatic(triangles(0x00ff00, 0xff0000, (byte) 0, true), TEST_VIEW);
        assertEquals(ModelRenderer.BACKGROUND, image.getRGB(256, 256) & 0xffffff);
    }

    @Test public void translucentNearSurfaceBlendsOverFarSurface()
    {
        BufferedImage image = new ModelRenderer().renderStatic(triangles(0x00ff00, 0xff0000, (byte) 128, false), TEST_VIEW);
        assertEquals(0x807f00, image.getRGB(256, 256) & 0xffffff); // Native GPU alpha uses transparency / 255.
    }

    @Test public void fullyTransparentAndHiddenFacesDoNotOcclude()
    {
        ModelRenderer renderer = new ModelRenderer();
        assertEquals(0xff0000, renderer.renderStatic(triangles(0x00ff00, 0xff0000, (byte) 255, false), TEST_VIEW)
            .getRGB(256, 256) & 0xffffff);
        assertEquals(0xff0000, renderer.renderStatic(triangles(-1, 0xff0000, (byte) 0, false), TEST_VIEW)
            .getRGB(256, 256) & 0xffffff);
    }

    @Test(expected = IllegalArgumentException.class)
    public void excessiveOverdrawIsRejected()
    {
        ModelSnapshot source = triangles(0x00ff00, 0xff0000, (byte) 0, false);
        int[] a = new int[100], b = new int[100], c = new int[100], colors = new int[100];
        java.util.Arrays.fill(b, 2);
        java.util.Arrays.fill(c, 1);
        java.util.Arrays.fill(colors, 0x00ff00);
        new ModelRenderer().renderStatic(new ModelSnapshot(source.x, source.y, source.z,
            a, b, c, colors, colors, colors, new byte[100]),
            new CameraView(TEST_VIEW.yaw, TEST_VIEW.pitch, 3));
    }

    @Test public void degenerateGeometryProducesBackground()
    {
        ModelSnapshot point = new ModelSnapshot(new float[]{0}, new float[]{0}, new float[]{0},
            new int[]{0}, new int[]{0}, new int[]{0}, new int[]{0xff0000}, new int[]{0xff0000},
            new int[]{0xff0000}, new byte[]{0});
        assertEquals(ModelRenderer.BACKGROUND, new ModelRenderer().renderStatic(point).getRGB(256, 256) & 0xffffff);
    }
}

package com.modelpopout;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class ModelScenePainterTest
{
    @Test public void npcFacesTowardPlayerAcrossCameraSidesWithoutChangingPlayerView()
    {
        assertFalse(ModelScenePainter.shouldMirrorNpc(CameraView.DEFAULT));
        assertFalse(ModelScenePainter.shouldMirrorNpc(new CameraView(Math.PI/2,0,1))); // already faces left
        assertFalse(ModelScenePainter.shouldMirrorNpc(new CameraView(Math.PI,0,1)));
        assertTrue(ModelScenePainter.shouldMirrorNpc(new CameraView(3*Math.PI/2,0,1))); // otherwise faces right
        assertTrue(ModelScenePainter.shouldMirrorNpc(new CameraView(-Math.PI/2,.5,2)));
    }

    @Test public void mirrorReflectsOnlyNpcPixelsPreservingIntrinsicAlphaAndSourceAcrossAnimationFrames()
    {
        for (int pose = 0; pose < 3; pose++)
        {
            BufferedImage scene = new BufferedImage(1024,512,BufferedImage.TYPE_INT_ARGB);
            scene.setRGB(100+pose,250,0xffff0000);
            scene.setRGB(512+70+pose,250,0xff000000);
            scene.setRGB(512+120+pose,250,0x8000ff00);
            int[] source = scene.getRGB(0,0,1024,512,null,0,1024);
            BufferedImage mirrored = paint(scene,true,true,1024,512);
            BufferedImage original = paint(scene,true,false,1024,512);
            for (int x = 0; x < 512; x++)
            {
                assertEquals(scene.getRGB(x,250),mirrored.getRGB(x,250));
                assertEquals(original.getRGB(512+x,250),mirrored.getRGB(1023-x,250));
            }
            assertEquals(255,mirrored.getRGB(1023-70-pose,250) >>> 24);
            assertEquals(128,mirrored.getRGB(1023-120-pose,250) >>> 24);
            assertArrayEquals(source,scene.getRGB(0,0,1024,512,null,0,1024));
        }
    }

    @Test public void mirrorRespectsCenteredSlotBoundsDuringResizeAndDoesNotAffectPlayerOnlyScene()
    {
        BufferedImage scene = new BufferedImage(1024,512,BufferedImage.TYPE_INT_ARGB);
        scene.setRGB(0,0,0xffff0000);
        scene.setRGB(512,0,0xff000000);
        BufferedImage resized = paint(scene,true,true,1024,600);
        assertEquals(0xffff0000,resized.getRGB(0,44));
        assertEquals(0xff000000,resized.getRGB(1023,44));
        assertEquals(0,resized.getRGB(0,43));
        assertArrayEquals(paint(scene,false,false,512,512).getRGB(0,0,512,512,null,0,512),
            paint(scene,false,true,512,512).getRGB(0,0,512,512,null,0,512));
    }

    static BufferedImage paint(BufferedImage scene, boolean npc, boolean mirror, int width, int height)
    {
        BufferedImage target = new BufferedImage(width,height,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = target.createGraphics();
        try { ModelScenePainter.paint(g,scene,npc,mirror,width,height); }
        finally { g.dispose(); }
        return target;
    }
}

package com.modelpopout;

import net.runelite.api.Model;
import net.runelite.api.Texture;
import net.runelite.api.TextureProvider;
import org.junit.Test;
import static org.junit.Assert.*;

public class ModelSnapshotTest
{
    private static final class MutableModel extends TestModel
    {
        final float[] x = {-10, 10, 0}, y = {-10, -10, 10}, z = {0, 0, 0};
        final int[] a = {0}, b = {1}, c = {2}, ca = {10000}, cb = {10000}, cc = {-1};
        final byte[] alpha = {0};
        final short[] textures = {-1};
        @Override public int getVerticesCount() { return 3; }
        @Override public float[] getVerticesX() { return x; }
        @Override public float[] getVerticesY() { return y; }
        @Override public float[] getVerticesZ() { return z; }
        @Override public int getFaceCount() { return 1; }
        @Override public int[] getFaceIndices1() { return a; }
        @Override public int[] getFaceIndices2() { return b; }
        @Override public int[] getFaceIndices3() { return c; }
        @Override public int[] getFaceColors1() { return ca; }
        @Override public int[] getFaceColors2() { return cb; }
        @Override public int[] getFaceColors3() { return cc; }
        @Override public byte[] getFaceTransparencies() { return alpha; }
        @Override public short[] getFaceTextures() { return textures; }
        @Override public Model getModel() { return this; }
    }

    @Test public void sharedNativeModelCanAdvanceWithoutMutatingEarlierSnapshot()
    {
        MutableModel model = new MutableModel();
        ModelSnapshot first = ModelSnapshot.capture(model.getModel(), null);
        model.y[0] = -20;
        model.ca[0] = 20000;
        model.alpha[0] = 127;
        ModelSnapshot second = ModelSnapshot.capture(model.getModel(), null);
        assertFalse(first.sameAppearance(second));
        assertEquals(-10, first.y[0], 0);
        assertEquals(10000, first.colorA[0]);
        assertEquals(0, first.alpha[0]);
        assertEquals(-20, second.y[0], 0);
    }

    @Test public void conversionIsDeferredCachedAndDoesNotModifyCapturedColors()
    {
        MutableModel model = new MutableModel();
        ModelSnapshot snapshot = ModelSnapshot.capture(model, null);
        assertEquals(10000, snapshot.colorA[0]);
        ModelSnapshot rgb = snapshot.toRgb();
        assertEquals(ModelSnapshot.hslToRgb(10000), rgb.colorA[0]);
        assertEquals(rgb.colorA[0], rgb.colorB[0]);
        assertEquals(rgb.colorA[0], rgb.colorC[0]);
        assertSame(rgb, snapshot.toRgb());
        assertEquals(10000, model.ca[0]);
        assertEquals(-1, model.cc[0]);
        assertEquals(10000, snapshot.colorA[0]);
    }

    @Test public void hiddenFacesStayHiddenDuringConversion()
    {
        MutableModel model = new MutableModel();
        model.cc[0] = -2;
        assertEquals(-1, ModelSnapshot.capture(model, null).toRgb().colorC[0]);
    }

    @Test public void textureFallbackLightingIsCopiedWithoutLoadingTexturePixels()
    {
        MutableModel model = new MutableModel();
        model.textures[0] = 0;
        model.ca[0] = 64;
        TextureProvider provider = new TextureProvider()
        {
            @Override public int getDefaultColor(int id) { assertEquals(0, id); return 30000; }
            @Override public double getBrightness() { return .8; }
            @Override public void setBrightness(double value) { throw new UnsupportedOperationException(); }
            @Override public Texture[] getTextures() { throw new UnsupportedOperationException(); }
            @Override public int[] load(int id) { throw new UnsupportedOperationException(); }
        };
        ModelSnapshot captured = ModelSnapshot.capture(model, provider);
        int packed = (30000 & 0xff80) | ((30000 & 127) * 64 / 128);
        assertEquals(packed, captured.colorA[0]);
        assertEquals(ModelSnapshot.hslToRgb(packed), captured.toRgb().colorA[0]);
        assertEquals(64, model.ca[0]);
    }

    @Test public void equalSnapshotContentIsDetectedWithoutModelIdentity()
    {
        MutableModel model = new MutableModel();
        ModelSnapshot first = ModelSnapshot.capture(model, null);
        assertTrue(first.sameAppearance(ModelSnapshot.capture(new MutableModel(), null)));
        model.b[0] = 2;
        assertFalse(first.sameAppearance(ModelSnapshot.capture(model, null)));
    }
    @Test(expected = IllegalArgumentException.class)
    public void shortVertexArraysAreRejectedInsteadOfInventingZeroVertices()
    {
        ModelSnapshot.capture(new TextureRenderingTest.TexturedModel()
        {
            @Override public float[] getVerticesX(){return new float[]{1};}
        },null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void missingFaceColorsAreRejectedExplicitly()
    {
        ModelSnapshot.capture(new TextureRenderingTest.TexturedModel()
        {
            @Override public int[] getFaceColors3(){return null;}
        },null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void shortOptionalTextureAssignmentsAreRejectedInsteadOfInventingTextureZero()
    {
        ModelSnapshot.capture(new TextureRenderingTest.TexturedModel()
        {
            @Override public short[] getFaceTextures(){return new short[0];}
        },null);
    }

    @Test public void spareCapacityIsAllowedButNeverRetained()
    {
        ModelSnapshot snapshot=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel()
        {
            @Override public float[] getVerticesX(){return new float[]{-80,80,-80,999};}
        },null);
        assertEquals(3,snapshot.x.length);
    }

}

package com.modelpopout;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GraphicsEnvironment;
