        assertSame(other,NpcSelector.select(other,corpse,Arrays.asList(npc(corpse,1,true,false,true),npc(other,2,true,true,false))));
        assertSame(other,NpcSelector.select(null,corpse,Arrays.asList(npc(corpse,1,false,false,true),npc(other,2,true,true,false))));
    }

    @Test public void nonCombatFollowersAreNotFallbackAttackers()
    {
        Object follower = new Object();
        assertNull(NpcSelector.select(null,null,Arrays.asList(new NpcSelector.Candidate<>(follower,1,true,true,false,false))));
    }
}

package com.modelpopout;

import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import org.junit.Test;
import static org.junit.Assert.*;

public class NpcTargetTrackerTest
{
    private static final class World extends TestWorldView
    {
        final Map<Integer,NPC> live = new LinkedHashMap<>();
        int scans;
        final IndexedObjectSet<NPC> set = new IndexedObjectSet<NPC>()
        {
            @Override public NPC byIndex(int index) { return live.get(index); }
            @Override public Iterator<NPC> iterator() { scans++; return live.values().iterator(); }
        };
        @Override public IndexedObjectSet<NPC> npcs() { return set; }
    }

    private static final class Player extends TestPlayer
    {
        final World world = new World();
        Actor target;
        @Override public WorldView getWorldView() { return world; }
        @Override public Actor getInteracting() { return target; }
    }

    private static final class Npc extends TestNpc
    {
        final World world;
        final int index;
        Actor target;
        int combat = 1, id = 1, animation = -1;
        boolean dead;
        Npc(Player player,int index) { world=player.world; this.index=index; world.live.put(index,this); }
        @Override public WorldView getWorldView() { return world; }
        @Override public int getIndex() { return index; }
        @Override public int getCombatLevel() { return combat; }
        @Override public int getId() { return id; }
        @Override public int getAnimation() { return animation; }
        @Override public boolean isDead() { return dead; }
        @Override public Actor getInteracting() { return target; }
    }

    @Test public void targetsSwitchAndSeedScanIsNotRepeatedPerFrame()
    {
        Player player = new Player();
        Npc a = new Npc(player,1), b = new Npc(player,2);
        a.target = b.target = player;
        player.target = b;
        NpcTargetTracker tracker = new NpcTargetTracker();
        NpcTargetTracker.Selection first = tracker.select(player,10);
        assertSame(b,first.npc);
        for(int i = 0; i < 20; i++) assertSame(b,tracker.select(player,10).npc);
        assertEquals(1,player.world.scans);
        player.target = a;
        NpcTargetTracker.Selection switched = tracker.select(player,10);
        assertSame(a,switched.npc);
        assertTrue(first.key != switched.key);
        player.target = null;
        assertSame(a,tracker.select(player,10).npc);
    }

    @Test public void despawnAndReusedNpcIndexCannotReuseSelectionIdentity()
    {
        Player player = new Player();
        Npc old = new Npc(player,7);
        player.target = old;
        NpcTargetTracker tracker = new NpcTargetTracker();
        NpcTargetTracker.Selection first = tracker.select(player,10);
        player.world.live.remove(7);
        assertEquals(first.key,tracker.despawned(old));
        assertNull(tracker.select(player,10).npc); // Player still holds a stale native pointer.
        Npc replacement = new Npc(player,7);
        replacement.target = player;
        tracker.spawned(replacement);
        NpcTargetTracker.Selection next = tracker.select(player,10);
        assertSame(replacement,next.npc);
        assertTrue(first.key != next.key);
    }

    @Test public void livingNpcIsRemovedWhenBothInteractionsEnd()
    {
        Player player = new Player();
        Npc npc = new Npc(player,1);
        npc.target = player;
        NpcTargetTracker tracker = new NpcTargetTracker();
        assertSame(npc,tracker.select(player,10).npc);
        npc.target = null; player.target = null;
        tracker.interaction(npc,null);
        assertNull(tracker.select(player,10).npc);
    }

    @Test public void deathPoseRetainedUntilDespawnAndNewTargetCanInterruptIt()
    {
        Player player = new Player();
        Npc dying = new Npc(player,1), other = new Npc(player,2);
        player.target = dying;
        NpcTargetTracker tracker = new NpcTargetTracker();
        NpcTargetTracker.Selection first = tracker.select(player,10);
        dying.dead = true; dying.animation = 100; player.target = null;
        tracker.interaction(dying,null);
        assertSame(dying,tracker.select(player,10).npc);
        player.target = other;
        assertSame(other,tracker.select(player,10).npc);
        player.target = null;
        assertNull(tracker.select(player,10).npc);
        player.world.live.remove(1);
        assertEquals(-1,tracker.despawned(dying));
        assertTrue(first.key != tracker.serial());
    }

    @Test public void finishedDeathAnimationRemovesPersistentCorpseEvenWithStalePlayerInteraction()
    {
        Player player = new Player();
        Npc corpse = new Npc(player,1);
        player.target = corpse;
        NpcTargetTracker tracker = new NpcTargetTracker();
        tracker.select(player,10);
        corpse.dead = true; corpse.animation = 100;
        assertSame(corpse,tracker.select(player,10).npc);
        corpse.animation = -1;
        assertNull(tracker.select(player,10).npc);
        assertSame(corpse,player.world.live.get(1)); // Has not despawned; the death action has ended.
    }

    @Test public void transformsPreserveIdentityAndCleanupCreatesFreshSession()
    {
        Player player = new Player();
        Npc npc = new Npc(player,1);
        player.target = npc;
        NpcTargetTracker tracker = new NpcTargetTracker();
        NpcTargetTracker.Selection first = tracker.select(player,10);
        npc.id = 200;
        tracker.spawned(npc);
        assertEquals(first.key,tracker.select(player,10).key);
        tracker.clear(); // Same cleanup operation is used by window close, logout, and plugin stop.
        NpcTargetTracker.Selection reopened = tracker.select(player,11);
        assertSame(npc,reopened.npc);
        assertTrue(first.key != reopened.key);
        assertEquals(2,player.world.scans);
    }
}

package com.modelpopout;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class PlayerFrameTraceTest
{
    @Test public void distinguishesNullBlankAlphaAndPlayerSlotFromNpcPixels()
    {
        assertEquals("null",PlayerFrameTrace.pixels(null));
        BufferedImage scene=new BufferedImage(1024,512,BufferedImage.TYPE_INT_ARGB);
        String blank=PlayerFrameTrace.pixels(scene);
        assertTrue(blank.contains("visible=0 opaque=0 alpha=0"));
        scene.setRGB(600,10,0xffffffff);assertEquals(blank,PlayerFrameTrace.pixels(scene));
        scene.setRGB(10,10,0x80ff0000);
        assertTrue(PlayerFrameTrace.pixels(scene).contains("visible=1 opaque=0 alpha=128"));
        scene.setRGB(10,10,0xffff0000);
        assertTrue(PlayerFrameTrace.pixels(scene).contains("visible=1 opaque=1 alpha=255"));
    }
    @Test public void traceIsBoundedAndDrainingDoesNotRetainRecords()
    {
        PlayerFrameTrace trace=new PlayerFrameTrace();
        for(int i=0;i<5000;i++)trace.record("capture","id="+i);
        String records=trace.drain();
        assertTrue(records.startsWith("dropped=904\n"));
        assertFalse(records.contains("id=0\n"));assertTrue(records.contains("id=4999"));
        assertEquals(4097,records.split("\n").length);
        assertEquals("dropped=0\n",trace.drain());
    }
    @Test public void fixedAndLiveCompletedScenesRemainImmutableWithAndWithoutHud()
    {
        ModelSnapshot mesh=ModelSnapshot.capture(new TextureRenderingTest.TexturedModel(),null);
        ModelFrame frame=ModelFrame.initial(mesh);CameraView camera=new CameraView(0,0,1);
        ModelRenderer renderer=new ModelRenderer();
        BufferedImage fixed=renderer.render(mesh,camera,frame,TextureSet.EMPTY,0);
        String fixedPixels=PlayerFrameTrace.pixels(fixed);
        assertFalse(fixedPixels.contains("visible=0 "));
        for(boolean frozen:new boolean[]{false,true})for(boolean npc:new boolean[]{false,true})for(boolean hud:new boolean[]{false,true})for(int cycle=100;cycle<110;cycle++)
        {
            TextureRenderingTest.TexturedModel animated=new TextureRenderingTest.TexturedModel();
            animated.y[0] += cycle-100;
            BufferedImage source=frozen?fixed:renderer.render(ModelSnapshot.capture(animated,null),camera,frame,TextureSet.EMPTY,0);
            BufferedImage scene=new BufferedImage(npc?1024:512,512,BufferedImage.TYPE_INT_ARGB);
            Graphics2D compose=scene.createGraphics();
            try{compose.drawImage(source,0,0,null);if(npc)compose.drawImage(source,512,0,null);}finally{compose.dispose();}
            String before=PlayerFrameTrace.pixels(scene);
            BufferedImage destination=new BufferedImage(scene.getWidth(),512,BufferedImage.TYPE_INT_ARGB);
            Graphics2D g=destination.createGraphics();
            try
            {
                ModelScenePainter.paint(g,scene,npc,true,destination.getWidth(),512);
                if(hud)
                {
                    HudSnapshot packet=new HudSnapshot(1,cycle,8,
                        new HudSnapshot.ActorHud(7,HudHealth.scaled(cycle-100,30),java.util.List.of()),
                        new HudSnapshot.ActorHud(8,HudHealth.scaled(15,30),java.util.List.of()),HudAssets.HealthSkin.FALLBACK);
                    HudAnchor anchor=HudAnchor.initial(mesh,frame);
                    HudPainter.paint(g,packet,anchor,anchor,camera,destination.getWidth(),512,npc,true,7,8,true,true);
                }
            }finally{g.dispose();}
            assertEquals(before,PlayerFrameTrace.pixels(scene));assertEquals(fixedPixels,PlayerFrameTrace.pixels(fixed));
            for(int y=0;y<512;y++)for(int x=0;x<512;x++)
                assertTrue("HUD cannot lower player alpha",(destination.getRGB(x,y)>>>24)>=(scene.getRGB(x,y)>>>24));
            // A camera-only render also must not modify the previously published cached image.
            renderer.render(mesh,new CameraView(0,.01*(cycle-100),1),frame,TextureSet.EMPTY,0);
            assertEquals(fixedPixels,PlayerFrameTrace.pixels(fixed));
        }
    }
}

package com.modelpopout;

import java.awt.image.BufferedImage;
import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.*;

public class StableFramingTest
{
    private static final int TORSO = 0xee5533, AXE = 0x33aaee;

    /** The torso never moves; the axe changes both vertical and horizontal bounds. */
    private ModelSnapshot pose(float axeY, float reach)
    {
        return new ModelSnapshot(new float[]{-20,20,-20,20,20,-20,reach,reach+25,reach+10},
            new float[]{-100,-100,0,-100,0,0,axeY,axeY,axeY+30},new float[9],
            new int[]{0,3,6},new int[]{2,5,8},new int[]{1,4,7},
            new int[]{TORSO,TORSO,AXE},new int[]{TORSO,TORSO,AXE},
            new int[]{TORSO,TORSO,AXE},new byte[3]);
    }

    private BufferedImage render(ModelRenderer renderer, LiveViewState.RenderRequest request)
    {
        return renderer.render(request.model, request.camera, request.framing);
    }

    @Test public void unmovingTorsoStaysAtSamePixelPositionAndSizeWhileAxeSwings()
    {
        LiveViewState state = new LiveViewState();
        state.setCamera(new CameraView(0, 0, 1));
        state.updateModel(pose(-80,45), false);
        LiveViewState.RenderRequest first = state.begin();
        ModelRenderer renderer = new ModelRenderer();
        boolean[] baseline = colorMask(render(renderer, first), TORSO);
        int[] originalBounds = colorBounds(render(renderer, first), TORSO);
        assertTrue(originalBounds[2] > originalBounds[0]);
        assertTrue(originalBounds[3] > originalBounds[1]);
        state.finish(first);
        for (int swing = 1; swing <= 12; swing++)
        {
            state.updateModel(pose(-80 - swing * 12,45 + swing * 5), false);
            LiveViewState.RenderRequest next = state.begin();
            assertNotNull(next);
            assertSame(first.framing, next.framing);
            assertSame(first.camera, next.camera);
            BufferedImage image = render(renderer, next);
            assertTrue("Stable body pixels despite changing animated bounds",
                Arrays.equals(baseline, colorMask(image, TORSO)));
            assertArrayEquals(originalBounds, colorBounds(image, TORSO));
            assertEquals(first.framing.scale(first.camera), next.framing.scale(next.camera), 0);
            state.finish(next);
        }
    }

    @Test public void extendedAnimationFitsReservedFrameAtDefaultZoomDuringOrbit()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(-80,45), false);
        LiveViewState.RenderRequest first = state.begin();
        state.finish(first);
        state.updateModel(pose(-210,100), false);
        ModelRenderer renderer = new ModelRenderer();
        for (int angle = 0; angle < 16; angle++)
        {
            state.setCamera(new CameraView(angle * Math.PI / 8, Math.toRadians(angle % 2 == 0 ? 75 : -75), 1));
            LiveViewState.RenderRequest request = state.begin();
            assertSame(first.framing, request.framing);
            assertVerticesInside(request);
            BufferedImage image = render(renderer, request);
            for (int edge = 0; edge < ModelRenderer.SIZE; edge++)
            {
                assertEquals(0, image.getRGB(edge,0) >>> 24);
                assertEquals(0, image.getRGB(edge,511) >>> 24);
                assertEquals(0, image.getRGB(0,edge) >>> 24);
                assertEquals(0, image.getRGB(511,edge) >>> 24);
            }
            state.finish(request);
        }
        state.setCamera(new CameraView(0,0,1));
        BufferedImage front = render(renderer,state.begin());
        int[] axeBounds = colorBounds(front,AXE);
        assertTrue("Raised axe visible",axeBounds[2] >= axeBounds[0]);
        assertTrue(axeBounds[1] > 0 && axeBounds[3] < 511);
    }

    @Test public void manualCaptureEquipmentChangeAndTemporaryModelLossDoNotRefit()
    {
        LiveViewState state = new LiveViewState();
        CameraView camera = new CameraView(1, .5, 1.5);
        state.setCamera(camera);
        state.updateModel(pose(-80,45),false);
        LiveViewState.RenderRequest first = state.begin();
        state.finish(first);
        state.updateModel(pose(-210,100),true);
        LiveViewState.RenderRequest manual = state.begin();
        assertSame(first.framing,manual.framing);
        assertSame(camera,manual.camera);
        state.finish(manual);
        state.clear();
        state.updateModel(pose(-180,90),false);
        LiveViewState.RenderRequest restored = state.begin();
        assertSame(first.framing,restored.framing);
        assertSame(camera,restored.camera);
    }

    @Test public void newViewerSessionEstablishesNewReferenceWithoutChangingOldRequest()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(-80,45),false);
        LiveViewState.RenderRequest old = state.begin();
        double oldCenter = old.framing.centerY;
        state.resetFraming();
        state.updateModel(pose(-210,100),false);
        assertNull(state.begin()); // Retains actual worker backpressure across reopen.
        assertFalse(state.finish(old));
        LiveViewState.RenderRequest fresh = state.begin();
        assertNotSame(old.framing,fresh.framing);
        assertTrue(oldCenter != fresh.framing.centerY);
        assertEquals(oldCenter,old.framing.centerY,0);
    }

    @Test public void manualRotationAndZoomChangeProjectionWithoutChangingReference()
    {
        LiveViewState state = new LiveViewState();
        state.updateModel(pose(-80,45),false);
        LiveViewState.RenderRequest first = state.begin();
        double originalScale = first.framing.scale(first.camera);
        state.finish(first);
        CameraView turned = first.camera.drag(50,-20).wheel(-2);
        state.setCamera(turned);
        LiveViewState.RenderRequest rotated = state.begin();
        assertSame(first.framing,rotated.framing);
        assertSame(turned,rotated.camera);
        assertEquals(originalScale * turned.zoom, rotated.framing.scale(turned),1e-12);
        assertTrue(first.camera.yaw != turned.yaw);
        assertTrue(first.camera.pitch != turned.pitch);
        state.finish(rotated);
        state.updateModel(pose(-210,100),false);
        LiveViewState.RenderRequest animated = state.begin();
        assertSame(turned,animated.camera);
        assertEquals(rotated.framing.scale(turned),animated.framing.scale(turned),0);
    }

    private void assertVerticesInside(LiveViewState.RenderRequest request)
    {
        ModelSnapshot mesh = request.model;
        ModelFrame frame = request.framing;
        // The reference sphere encloses the reserved motion, guaranteeing containment for any orbit.
        double usableRadius = ModelRenderer.SIZE / 2.0 / frame.scale(request.camera);
        for(int i = 0; i < mesh.x.length; i++)
        {
            double x = mesh.x[i]-frame.centerX, y = mesh.y[i]-frame.centerY, z = mesh.z[i]-frame.centerZ;
            assertTrue(Math.sqrt(x*x+y*y+z*z) < usableRadius);
        }
    }

    private boolean[] colorMask(BufferedImage image, int color)
    {
        boolean[] mask = new boolean[512*512];
        for(int y = 0; y < 512; y++) for(int x = 0; x < 512; x++)
            mask[y*512+x] = (image.getRGB(x,y) & 0xffffff) == color;
        return mask;
    }

    private int[] colorBounds(BufferedImage image, int color)
    {
        int minX=512,minY=512,maxX=-1,maxY=-1;
        for(int y = 0; y < 512; y++) for(int x = 0; x < 512; x++)
        {
            if((image.getRGB(x,y) & 0xffffff) != color) continue;
            minX=Math.min(minX,x); minY=Math.min(minY,y);
            maxX=Math.max(maxX,x); maxY=Math.max(maxY,y);
        }
        return new int[]{minX,minY,maxX,maxY};
    }
}

